INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p1-3', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'UNKNOWN', 1, 'Related work: This specification replaces or supersedes: ● TAXII Version 2.0. Edited by John Wunder, Mark Davidson, and Bret Jordan. Latest stage: http://docs.oasis-open.org/cti/taxii/v2.0/taxii-v2.0.html. ● TAXII Version 1.1.1. Part 1: Overview. Edited by Mark Davidson, Charles Schmidt, and Bret Jordan. Latest stage: http://docs.oasis-open.org/cti/taxii/v1.1.1/taxii-v1.1.1-part1-overview.html. This specification is related to: • STIX Version 2.1. Edited by Bret Jordan, Rich Piazza, and Trey Darley. Latest stage: http://docs.oasis-open.org/cti/stix/v2.1/stix-v2.1.html. Abstract: TAXII is an application layer protocol for the communication of cyber threat information in a simple and scalable manner. This specification defines the TAXII RESTful API and its resources along with the requirements for TAXII Client and Server implementations. Status: This document was last revised or approved by the membership of OASIS on the above date. The level of approval is also listed above.', 'vec_doc-11-oasis-taxii21-p1-3', 0, 247, 'v2.1.0', '9e9afb0536d77254064ea1a9b2750740fdd84da9d9600b6199a953653c4c4f12', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":1,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":3,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"General Document Content"}');
