INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p2-5', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'UNKNOWN', 2, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 2 of 79 TC members should send comments on this document to the TC''s email list. Others should send comments to the TC''s public comment list, after subscribing to it by following the instructions at the "Send A Comment" button on the TC''s web page at https://www.oasis-open.org/committees/cti/. This specification is provided under the Non-Assertion Mode of the OASIS IPR Policy, the mode chosen when the Technical Committee was established. For information on whether any patents have been disclosed that may be essential to implementing this specification, and any offers of patent licensing terms, please refer to the Intellectual Property Rights section of the TC''s web page (https://www.oasis- open.org/committees/cti/ipr.php). Note that any machine-readable content (Computer Language Definitions) declared Normative for this Work Product is provided in separate plain text files. In the event of a discrepancy between any such plain text file and display content in the Work Product''s prose narrative document(s), the content in the separate plain text file prevails. Citation format: When referencing this specification, the following citation format should be used: [TAXII-v2.1] TAXII Version 2.1. Edited by Bret Jordan and Drew Varner. 10 June 2021. OASIS Standard. https://docs.oasis-open.org/cti/taxii/v2.1/os/taxii-v2.1-os.html. Latest stage: https://docs.oasis- open.org/cti/taxii/v2.1/taxii-v2.1.html.', 'vec_doc-11-oasis-taxii21-p2-5', 0, 382, 'v2.1.0', '872ef755406cf67231e76986e0cdedfd030bb6faac2fa8521e6a410bbbc081a4', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":2,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":5,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"General Document Content"}');
