INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p7-27', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'UNKNOWN', 7, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 7 of 79 1 Introduction TAXII is an application layer protocol for the communication of cyber threat information in a simple and scalable manner. This specification defines the TAXII RESTful API and its resources along with the requirements for TAXII Client and Server implementations.', 'vec_doc-11-oasis-taxii21-p7-27', 0, 99, 'v2.1.0', '3bdbb049283ccd29033878e9fe29e2bbe9913ef63843ec742fe697b97027719a', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":7,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":27,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p7-28', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.1 IPR Policy', 7, 'This specification is provided under the Non-Assertion Mode of the OASIS IPR Policy, the mode chosen when the Technical Committee was established. For information on whether any patents have been disclosed that may be essential to implementing this specification, and any offers of patent licensing terms, please refer to the Intellectual Property Rights section of the TC’s web page ( https://www.oasis- open.org/committees/cti/ipr.php).', 'vec_doc-11-oasis-taxii21-p7-28', 0, 110, 'v2.1.0', '6b7382f008ea550f28aea5a52d7edceea23bed2ef004478d04a591280790dabc', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.1 IPR Policy","subsection":"UNKNOWN","table_id":null,"page":7,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":28,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.1 IPR Policy"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p7-29', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.2 Terminology', 7, 'The key words "MUST", "MUST NOT", "REQUIRED", "SHALL", "SHALL NOT", "SHOULD", "SHOULD NOT", "RECOMMENDED", "NOT RECOMMENDED", "MAY", and "OPTIONAL" in this document are to be interpreted as described in BCP 14 [RFC2119] [RFC8174] when, and only when, they appear in all capitals, as shown here. All text is normative except for examples, the overview (section 1.6), and any text marked non-normative.', 'vec_doc-11-oasis-taxii21-p7-29', 0, 100, 'v2.1.0', '18c4a07ff1bafcd2c270e1372bc1ae175b51eef4eae6fe4a720b3b7700448007', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.2 Terminology","subsection":"UNKNOWN","table_id":null,"page":7,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":29,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.2 Terminology"}');
