 '1664d8782a092fa3b5dff431d58e148370f7d0db29556f30222ecbe70ebde6ca', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.4 Non-Normative References","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":36,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.4 Non-Normative References"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p10-37', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.4 Non-Normative References', 10, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 10 of 79 [RFC8322] Field, J., Banghart, S., and D. Waltermire, "Resource-Oriented Lightweight Information Exchange (ROLIE)", RFC 8322, DOI 10.17487/RFC8322, February 2018, https://www.rfc-editor.org/info/rfc8322. [IANA AUTH]  IANA, "Hypertext Transfer Protocol (HTTP) Authentication Scheme Registry", February 2014, https://www.iana.org/assignments/http-authschemes/http- authschemes.xhtml. [NIST RBAC]  NIST Computer Security Resource Center (CSRC), "Role Based Access Control (RBAC)", November 2016, https://csrc.nist.gov/projects/role-based-access-control. [UNICODE]  Davis, M. and Suignard, M., "UNICODE Security Considerations", Unicode Technical Report #36, September 2014, https://www.rfc-editor.org/info/rfc8322.', 'vec_doc-11-oasis-taxii21-p10-37', 0, 208, 'v2.1.0', '189f1476137ea3b0ab6b8888def28decd3356459d1d633b805e7444659df670c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.4 Non-Normative References","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":37,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.4 Non-Normative References"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p10-38', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.5 Document Conventions', 10, '1.5.1 Naming Conventions All type names, property names and literals are in lowercase. Words in property names are separated with an underscore (_), while words in type names and string enumerations are separated with a hyphen (Unicode hyphen-minus, U+002D, ‘-‘). All type names, property names, object names, and vocabulary terms are between three and 250 characters long. 1.5.2 Font Colors and Style The following color, font and font style conventions are used in this document: ● The Consolas font is used for all type names, property names and literals. ○ resource and type names are in red with a light red background – collection ○ property names are in bold style – description ○ parameter names in URLs are stylized with angled brackets - {api-root} ○ literals (values) are in blue with a blue background – complete ● All examples in this document are expressed in Consolas 9-point font, with straight quotes, black text, 2-space indentation, and sometimes in a light grey background. JSON examples in this document are representations of JSON Objects. They should not be interpreted as string literals. The ordering of object keys is insignificant. Whitespace before or after JSON structural characters in the examples are insignificant [RFC8259]. ● Parts of the example may be omitted for conciseness and clarity. These omitted parts are denoted with ellipses (...).', 'vec_doc-11-oasis-taxii21-p10-38', 0, 345, 'v2.1.0', '6cb8d33781bc940b3e4687ed6e6022dc18968b022ec335a43b554ac6e0700d6c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.5 Document Conventions","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":38,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.5 Document Conventions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p10-39', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 10, 'Trusted Automated Exchange of Intelligence Information (TAXII) is an application layer protocol used to exchange cyber threat intelligence (CTI) over HTTPS. TAXII enables organizations to share CTI by defining an API that aligns with common sharing models. Specifically, TAXII defines two primary services, Collections and Channels, to support a variety of commonly-used sharing models. Collections allow a producer to host a set of CTI data that can be requested by consumers. Channels allow producers to push data to many consumers; and allow consumers to receive data from many producers. Collections and Channels can be organized by grouping them into an API Root to support the needs of a particular trust group or to organize them in some other way. Note: This version of the TAXII specification reserves the keywords required for Channels but does not specify Channel services. Channels and their services will be defined in a subsequent version of this specification.', 'vec_doc-11-oasis-taxii21-p10-39', 0, 244, 'v2.1.0', '58f5379b4ac6e183ccafc9789a446a9129f2bc2dc775809df9d017cae9489a06', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":39,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p11-40', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 11, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 11 of 79 TAXII is specifically designed to support the exchange of CTI represented in STIX. As such, the examples and some features in the specification are intended to align with STIX. This does not mean TAXII cannot be used to share data in other formats; it is designed for STIX but is not limited to STIX. 1.6.1 Discovery This specification defines two discovery methods. The first is a network level discovery that uses a DNS SRV record [RFC2782]. This DNS SRV record can be used to advertise the location of a TAXII Server within a network (e.g., so that TAXII-enabled security infrastructure can automatically locate an organization''s internal TAXII Server) or to the general Internet. See section 3.9 for complete information on advertising TAXII Servers in DNS.', 'vec_doc-11-oasis-taxii21-p11-40', 0, 221, 'v2.1.0', 'd1ef0aea7424bd174a14c2b4a93d7da634bfccbb601116d31a8c95983f4e012c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":40,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p11-41', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 11, 'The second discovery method is a Discovery Endpoint (this specification uses the term Endpoint to identify a URL and an HTTP method with a defined request and response) that enables authorized clients to obtain information about a TAXII Server and get a list of API Roots. See section 4.1 for complete information on the Discovery Endpoint. 1.6.2 API Roots API Roots are logical groupings of TAXII Collections, Channels, and related functionality. A TAXII server instance can support one or more API Roots. API Roots can be thought of as instances of the TAXII API available at different URLs, where each API Root is the "root" URL of that particular instance of the TAXII API. Organizing the Collections and Channels into API Roots allows for a division of content and access control by trust group or any other logical grouping.', 'vec_doc-11-oasis-taxii21-p11-41', 0, 208, 'v2.1.0', 'f35527f83adc393f85928809f8d80e1dbe116e72fca96ace46c46cb4b4914ada', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":41,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p11-42', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 11, 'For example, a single TAXII Server could h ost multiple API Roots - one API Root for Collections and Channels used by Sharing Group A and another API Root for Collections and Channels used by Sharing Group B. Each API Root contains a set of Endpoints that a TAXII Client contacts in order to interac t with the TAXII Server. This interaction can take several forms: ● Server Discovery, as described above, can be used to learn about the API Roots hosted by a TAXII Server. ● Each API Root might support zero or more Collections. Interactions with Collections i nclude discovering the type of CTI contained in that Collection, pushing new CTI to that Collection, and/or retrieving CTI from that Collection. Each piece of CTI content in a Collection is referred to as an Object. ● Each API Root might host zero or more Channels. ● Each API Root also allows TAXII Clients to check on the Status of certain types of requests to the TAXII Server.', 'vec_doc-11-oasis-taxii21-p11-42', 0, 236, 'v2.1.0', 'a1afd1d2ec86e7a95b9eaa4cfe0c039574a9e09c24b02f417a5beefd7f976173', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":42,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p11-43', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 11, 'For example, if a TAXII Client submitted new CTI, a Status request can allow the Client to check on whether the new CTI was accepted. Figure 1.1 summarizes the relationships between the components of an API Root. Example API Root URLs https://example.com/ https://api1.example.com/ https://example.com/api1/ https://example.com/api2/ https://example.org/trustgroup1/ https://example.org/taxii2/api1/', 'vec_doc-11-oasis-taxii21-p11-43', 0, 100, 'v2.1.0', '1352c63f609723f4e347de852c24d50dd19cdeeb9557102b8130f1ef18f77a55', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":43,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p12-44', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 12, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 12 of 79 Figure 1.1 1.6.3 Endpoints An Endpoint consists of a specific URL and HTTP Method on a TAXII Server that a TAXII Client can contact to engage in one specific type of TAXII exchange. For example, each Collection on a TAXII Server has an Endpoint that can be used to get information about it; TAXII Clients can contact the Collection’s Endpoint to request a description of that Collection. A separate Endpoint is used for the TAXII Client to collect a manifest of that Collection’s Content. Yet another Endpoint is used to get objects from the Collection and, at the same URL, a POST can be used to add objects to the collection. The Endpoints supported by a TAXII Server are summarized in section 3.1 and fully defined in sections 4, 5, and 6.', 'vec_doc-11-oasis-taxii21-p12-44', 0, 216, 'v2.1.0', '91af7e9ec05fd421bc7508f867bdfd5d585d7cf1edda65a1d08f914039065fba', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":44,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p12-45', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 12, '1.6.4 Collections A TAXII Collection is an interface to a logical repository of CTI objects provided by a TAXII Server and is used by TAXII Clients to send information to the TAXII Server or request information from the TAXII Server. A TAXII Server can host multiple Collections per API Root, and Collections are used to exchange information in a request–response manner. Figure 1.2 below illustrates how Collection based communications are used when a single TAXII Client makes a request to a TAXII Server and the TAXII Server fulfills that request with information available to the TAXII Server (nominally from a database). 1.6.5 Channels A TAXII Channel is maintained by a TAXII Server and enables TAXII Clients to exchange information with other TAXII Clients in a publish-subscribe model. TAXII Clients can publish messages to Channels and subscribe to Channels to receive published messages. A TAXII Server may host multiple Channels per API Root.', 'vec_doc-11-oasis-taxii21-p12-45', 0, 239, 'v2.1.0', 'b455cde2d8e1e8afd85563cd7aaf5ee28d67b7ca1ea630a54d2380f6d96f80da', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":45,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p12-46', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 12, 'Figure 1.3 below illustrates how Channel communications are used when a single authorized TAXII Client sends a message to the TAXII Server, and that TAXII Server then distributes the message to all authorized TAXII Clients that are connected to the Channel. The arrows in the following diagrams represent data flow.', 'vec_doc-11-oasis-taxii21-p12-46', 0, 79, 'v2.1.0', 'e6feb9c0383a5b60711d620e41c995be03b66600f329818afd81bf0db222c69e', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":46,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p13-47', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 13, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 13 of 79 Figure 1.2           Figure 1.3 1.6.6 Transport The TAXII protocol defined in this specification uses HTTPS (HTTP over TLS) as the transport for all communications. 1.6.7 Serialization This specification uses UTF-8 encoded JSON as defined in [RFC7493] and [RFC8259] for the serialization of all TAXII resources. 1.6.8 Content Negotiation This specification uses media types (section 3.1.1.1 of [RFC7231]) and an optional "version" parameter in the HTTP Accept header (section 5.3.2 of [RFC7231]) and Content-Type header (section 3.1.1.5 of [RFC7231]) to perform HTTP content negotiation as defined in [RFC7231]. It is important that TAXII Clients and Servers use correct Accept and Content-Type headers to negotiate TAXII versions. 1.6.8.1 Media Types The TAXII media types used in this specification are summarized in the following table  and are used for both requests and responses. Appendix B contains the official IANA registration information for the TAXII media type. Type Subtype Example application taxii+json application/taxii+json 1.6.8.2 Version Parameter This section defines the optional version parameter that can be used with content negotiation. The version parameter is defined per the guidelines in section 4.3 of [RFC6838] and the value is of the form ''n.m'', where n is the major version and m the minor version, both unsigned integer values. The value for the version parameter that represents the final contents of this specification is "2.1".', 'vec_doc-11-oasis-taxii21-p13-47', 0, 397, 'v2.1.0', '81772a65f54f8041c94580c6f3e57a3424faa4928e059fe88968abb0ccd0444c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":47,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p14-48', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 14, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 14 of 79 Media Type with Optional Version Parameter Description application/taxii+json;version=2.1  TAXII version 2.1 in JSON application/taxii+json Latest version of TAXII that the server supports 1.6.9 Authentication and Authorization Access control to an instance of the TAXII API is specific to the sharing community, vendor, or product and is not defined by this specification. Authentication and Authorization in TAXII is implemented as defined in [RFC7235], using the  WWW- Authenticate and Authorization HTTP headers. HTTP Basic authentication, as defined in [RFC7617] is the suggested authentication scheme in TAXII. As specified in sections 8.2.2 and 8.5.1, TAXII Servers are encouraged to implement support for HTTP Basic and Clients are required to implement support for HTTP Basic, though other authentication schemes can also be supported.', 'vec_doc-11-oasis-taxii21-p14-48', 0, 242, 'v2.1.0', '57440cbc4cb6c18f821c03a7a4557244dba1d372f80bc9afc7e9371fdf4b6237', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":48,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p14-49', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 14, 'Implementers can allow operators to disable the use of HTTP Basic in their operations. If the TAXII Server receives a request for any Endpoint that requires authentication, regardless of HTTP method, and either an acceptable Authorization header that grants the client access to that object is not sent with the request or the TAXII Server does not determine via alternate means that the cli ent is authorized to access the resource, then the TAXII Server will respond with an HTTP 401 (Unauthorized) status code and a WWW-Authenticate HTTP header. The WWW-Authenticate header contains one or more challenges, which define which authentication schemes are supported by the TAXII Server. The format of the WWW-Authenticate HTTP header and any challenges are defined in [RFC7235]. To ensure compatibility, it is recommended that any authentication schemes used in challenges be registered in the IANA Hypertext Transfer Protocol (HTTP) Authentication Scheme Registry [HTTP Auth] .', 'vec_doc-11-oasis-taxii21-p14-49', 0, 245, 'v2.1.0', '96ff378adf2416d1d9f773207db4fed61ba31a1b25bc395f1c3cc3e4425de626', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":49,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p14-50', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.6 Overview', 14, 'A TAXII Server may omit objects, information, or optional properties from any response if the authenticated client is not authorized to receive them, so long as that omission does not violate this specification. 1.6.10 STIX and Other Content TAXII is designed with STIX in mind and to support the exchanging of STIX 2 [STIX Version 2.1] content. While additional content types are not prohibited, all specific requirements throughout the document are designed for STIX. See section 3.7 for more details. 1.6.11 Object Lifecycle There are no requirements defined in this specification for how long a TAXII server needs to store a specific object on the server or within a collection after it has been successfully posted to a TAXII collection. If the TAXII server chooses to remove an entire object or any number of versions of the object from the server or collection that is entirely up to the software, its deployment, and the use cases it supports.', 'vec_doc-11-oasis-taxii21-p14-50', 0, 238, 'v2.1.0', '26ab90f30efc3f6d32d41d6db2af0fc1af94cd11443ce69d24df723c8ffefc07', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.6 Overview","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":50,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.6 Overview"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p14-51', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1.7 Changes from Earlier Versions', 14, 'This section lists all of the major changes from the previous 2.0 version of TAXII.', 'vec_doc-11-oasis-taxii21-p14-51', 0, 21, 'v2.1.0', '46127188898096dd32d8a7960d468e635efa93f0dc2ac3f97ed8ee18d93370b5', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1.7 Changes from Earlier Versions","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":51,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1.7 Changes from Earlier Versions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p15-52', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3. The Manifest Resource was changed to represent individual versions of an object, instead of an', 15, 'object with all of its versions', 'vec_doc-11-oasis-taxii21-p15-52', 0, 8, 'v2.1.0', '048e8446a102471c8880d342a9dded6fd45a315d18597496cee1f0d0deda7530', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3. The Manifest Resource was changed to represent individual versions of an object, instead of an","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":52,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3. The Manifest Resource was changed to represent individual versions of an object, instead of an"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p15-53', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '21. Added user-agent HTTP header description', 15, 'Please see Appendix C for a list GitHub issues that were resolved for this release.', 'vec_doc-11-oasis-taxii21-p15-53', 0, 21, 'v2.1.0', '774cf5595ea0aa6adddabb6244f9374729227aac8dc55a35a2b77c9849e93706', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"21. Added user-agent HTTP header description","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":53,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"21. Added user-agent HTTP header description"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p16-54', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '21. Added user-agent HTTP header description', 16, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 16 of 79 2 Data Types This section defines the names and permitted values of common types used throughout this specification. These types are referenced by the “Type” column in other sections. This table do es not, however, define the meaning of any properties using these types. These types may be further restricted elsewhere in the document. Type Description api-root An API Root Resource, see section 4.2.1. boolean A boolean is a value of either true or false. Properties with this type MUST have a literal (unquoted) value of true or false. collection A Collection Resource, see section 5.2.1. collections A Collections Resource, see section 5.1.1. dictionary A dictionary is a JSON object that captures an arbitrary set of key/value pairs. discovery A Discovery Resource, see section 4.1.1. envelope A TAXII Envelope, see section 3.7. error An Error Message, see section 3.6.1.', 'vec_doc-11-oasis-taxii21-p16-54', 0, 249, 'v2.1.0', '5d5763286a8476f887b45e59202c23d36f24516b8070b9b433b515e5c9df771e', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"21. Added user-agent HTTP header description","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":54,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"21. Added user-agent HTTP header description"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p16-55', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '21. Added user-agent HTTP header description', 16, 'identifier An identifier is an RFC 4122-compliant Version 4 UUID. The UUID MUST be generated according to the algorithm(s) defined in RFC 4122, section 4.4 (Version 4 UUID) [RFC4122]. integer The integer data type represents a whole number. Unless otherwise specified, all integers MUST be capable of being represented as a signed 54-bit value  ([- (2**53)+1, (2**53)-1]) as defined in [RFC7493]. Additional restrictions MAY be placed on the type where it is used. list The list type defines a sequence of values ordered based on how they appear in the list. The phrasing “list of type <type>” is used to indicate that all values within the list MUST conform to the specified type. For instance, list of type integer means that all values of the list must be of the integer type. This specification does not specify the maximum number of allowed values in a list, however every instance of a list MUST have at least one value.', 'vec_doc-11-oasis-taxii21-p16-55', 0, 232, 'v2.1.0', '876056fd787c40ec8070faf0abedef3c8d277f684a6319a040d31eaa3deb73df', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"21. Added user-agent HTTP header description","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":55,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"21. Added user-agent HTTP header description"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p16-56', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '21. Added user-agent HTTP header description', 16, 'Specific TAXII resource properties may define more restrictive upper and/or lower bounds for the length of the list.', 'vec_doc-11-oasis-taxii21-p16-56', 0, 29, 'v2.1.0', '7428aff73c355927b8eaca35de2572f3a3453dcd69acb6cff45e48fe9bb8879b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"21. Added user-agent HTTP header description","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":56,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"21. Added user-agent HTTP header description"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p17-57', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '21. Added user-agent HTTP header description', 17, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 17 of 79 Empty lists are prohibited in TAXII and MUST NOT be used as a substitute for omitting optional properties. If the property is required, the list MUST be present and MUST have at least one value. The JSON MTI serialization uses the JSON array type [RFC8259], which is an ordered list of values. manifest A Manifest Resource, see section 5.3.1. object An Object Resource, see section 3.7. status A Status Resource, see section 4.3.1. string The string data type represents a finite-length string of valid characters from the Unicode coded character set [ISO10646] that are encoded in UTF-8. Unicode incorporates ASCII [RFC0020] and the characters of many other international character sets. timestamp The timestamp type defines how timestamps are represented in TAXII and is represented in serialization as a string. ● The timestamp type MUST be a valid RFC 3339-formatted timestamp [RFC3339] using the format YYYY-MM-DDTHH:MM:SS.ssssssZ Unlike the STIX timestamp type, the TAXII timestamp MUST have microsecond precision. ● The timestamp MUST be represented in the UTC timezone and MUST use the “Z” designation to indicate this. versions A Versions Resource, see section 5.8.1.', 'vec_doc-11-oasis-taxii21-p17-57', 0, 325, 'v2.1.0', '1e257342507da6d3960bc72c1cb9be8e46c870323e0a5df971a46e9c2c3e777a', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"21. Added user-agent HTTP header description","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":57,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"21. Added user-agent HTTP header description"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p18-58', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '21. Added user-agent HTTP header description', 18, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 18 of 79 3 TAXII - Core Concepts The TAXII API is described as sets of Endpoints. Each Endpoint is identified by the URL that it is accessible at and the HTTP method that is used to make the request. For example, the "Get Collections" Endpoint is requested by issuing a GET to `{api-root}/collections/`. Each Endpoint identifies its URL, which parameters it accepts (including both path parameters and standard parameters), which features it supports (e.g. filtering), and which content types it defines for request and response. It also identifies common error conditions and provides guidance on how to use the Endpoint. This section defines behavior that applies across Endpoints, such as normative requirements to support each Endpoint, sorting, filtering, and error handling.', 'vec_doc-11-oasis-taxii21-p18-58', 0, 223, 'v2.1.0', '29440fd78bcb53a32c55f093594de444ecb5272e24d414fdfcb8f7e65c336753', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"21. Added user-agent HTTP header description","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":58,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"21. Added user-agent HTTP header description"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p18-59', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.1 Endpoints', 18, 'Sections 4, 5 and 6 define the set of TAXII Endpoints used in the TAXII API. The following normative requirements apply to each Endpoint: ● The endpoint path in a requests to a TAXII server MUST end in a trailing slash "/". For example: ○ A request for a resource without any filter parameters /{api- root}/collections/{id}/objects/{object-id}/ ○ A request for a resource with some filter parameters. /{api- root}/collections/{id}/objects/{object-id}/?match[type]=indicator ● TAXII responses with an HTTP success code (200 series) that permit a response body MUST include the appropriate response body for the specified content type as identified in the definition of that Endpoint. ● TAXII responses with an HTTP error code (400-series and 500-series status codes, defined by sections 6.5 and 6.6 of [RFC7231]) that permit a response body (i.e. are not in response to a HEAD request) MAY contain an error message (see section 3.6.1) in the response body.', 'vec_doc-11-oasis-taxii21-p18-59', 0, 239, 'v2.1.0', 'ffc9741891233f9dd2a1fed5a45534ade9fd793b1ecefe7ff0e4980638c01851', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.1 Endpoints","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":59,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.1 Endpoints"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p18-60', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.1 Endpoints', 18, '● All TAXII requests MUST include a media range in the Accept header and MUST include at least one TAXII media range. Requests for TAXII content MUST use the values from section 1.6.8 and SHOULD include the optional version parameter defined in that section. ● All TAXII responses MUST include the appropriate media type and version parameter in the Content-Type header as defined for that Endpoint. ● TAXII responses SHOULD be the highest version of content that the server supports if the version parameter in the Accept header is omitted during content negotiation. ● Requests with media types in the Accept headers that are defined for that Endpoint MUST NOT result in an HTTP 406 (Not Acceptable) response. ● Requests with a media type in the Content-Type header that is defined for that Endpoint MUST NOT result in an HTTP 415 (Unacceptable Media Type) response.', 'vec_doc-11-oasis-taxii21-p18-60', 0, 217, 'v2.1.0', '8d1ba368db2b3ea0d253a53685b3a8974bb4c401ff000db9d9d46e420b007871', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.1 Endpoints","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":60,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.1 Endpoints"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p18-61', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.1 Endpoints', 18, '● Requests with media types in the Accept headers that are not defined for that Endpoint MAY be satisfied with the appropriate content or MAY result in an HTTP 406 (Not Acceptable) response. ● Requests with a media type in the Content-Type header that is not defined for that Endpoint MAY be satisfied with the appropriate content or MAY result in an HTTP 415 (Unacceptable Media Type) response. ● All TAXII POST requests MUST include a valid Accept and Content-Type header. ● TAXII responses to Endpoints that support filtering MUST filter results per the requirements in', 'vec_doc-11-oasis-taxii21-p18-61', 0, 143, 'v2.1.0', '8da4ea47b620e9a8608b89850684cbceed84e080a9d6a6155c1e236786ee86bd', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.1 Endpoints","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":61,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.1 Endpoints"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p18-62', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'section 3.4.', 18, '● The endpoint definition information in the tables found in sections 4 and 5 is normative. The following table provides a summary of the Endpoints (URLs and HTTP Methods) defined by TAXII and the Resources they operate on.', 'vec_doc-11-oasis-taxii21-p18-62', 0, 56, 'v2.1.0', '582cf029e6652d6308b092029456156b7858ba33d9953a94f1d1066383859159', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"section 3.4.","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":62,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"section 3.4."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p19-63', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'section 3.4.', 19, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 19 of 79 URL Methods Resource Type Core Concepts (section 4) /taxii2/ GET discovery {api-root}/ GET api {api-root}/status/{status-id}/ GET status Collections (section 5) {api-root}/collections/ GET collections {api-root}/collections/{id}/ GET collection {api-root}/collections/{id}/manifest/ GET manifest {api-root}/collections/{id}/objects/ GET, POST envelope {api-root}/collections/{id}/objects/{object-id}/ GET, DELETE envelope {api-root}/collections/{id}/objects/{object-id}/versions/ GET versions Channels (section 6) TBD in a future version', 'vec_doc-11-oasis-taxii21-p19-63', 0, 165, 'v2.1.0', '0d2ba61d4a02c7d7b3737cda4d455d1a36b944dc1ae597f98c57e8a987780e66', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"section 3.4.","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":63,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"section 3.4."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p19-64', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.2 HTTP Headers', 19, 'This section summarizes the HTTP headers and defines custom headers used by this specification. Type Description Standard Headers Accept The Accept header is used by HTTP Requests to specify which Content-Types are acceptable in response. TAXII defines a media type and an optional version parameter that can be used in the Accept header. See section 5.3.2 of [RFC7231].', 'vec_doc-11-oasis-taxii21-p19-64', 0, 93, 'v2.1.0', 'c6c43513b59ba55696fdec0671c298b61e0bdcfe2411833c0656a39f1c7e27e4', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.2 HTTP Headers","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":64,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.2 HTTP Headers"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p20-65', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.2 HTTP Headers', 20, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 20 of 79 Authorization The Authorization header is used by HTTP Requests to specify authentication credentials. See section 4.2 of [RFC7235]. Content-Type The Content-Type header is used by HTTP to identify the format of HTTP Requests and HTTP Responses. TAXII defines a media type and an optional version parameter that can be used in the Content- Type header. See section 3.1.1.5 of [RFC7231]. User-Agent The User-Agent header is used by HTTP to identify the TAXII Client software name and version. TAXII Clients SHOULD use the User- Agent header in requests to a TAXII Server as defined in section 5.5.3 of [RFC7231]. WWW-Authenticate The WWW-Authenticate header is used by HTTP Responses to indicate that authentication is required and to specify the authentication schemes and parameters that are supported. See', 'vec_doc-11-oasis-taxii21-p20-65', 0, 232, 'v2.1.0', '91298d0ad4f99e60a19f192d13840847fa89bda97b5b4ce637c205a8d4dbd2dc', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.2 HTTP Headers","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":65,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.2 HTTP Headers"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p20-66', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'section 4.1 of [RFC7235].', 20, 'Custom Headers X-TAXII-Date-Added-First The X-TAXII-Date-Added-First header is an extension header. It indicates the date_added timestamp of the first object of the response. The value of this header MUST be a timestamp. All HTTP 200 series responses to the following endpoints MUST include the X- TAXII-Date-Added-First header: ● GET {api-root}/collections/{id}/manifest/ ● GET {api-root}/collections/{id}/objects/ ● GET {api-root}/collections/{id}/objects/{object-id}/ ● GET {api-root}/collections/{id}/objects/{object-id}/versions/ Behaviour of this header on any other endpoint, is not defined. X-TAXII-Date-Added-Last The X-TAXII-Date-Added-Last header is an extension header. It indicates the date_added timestamp of the last object of the response. The value of this header MUST be a timestamp. All HTTP 200 series responses to the following endpoints MUST include the X- TAXII-Date-Added-Last header: ● GET {api-root}/collections/{id}/manifest/ ● GET {api-root}/collections/{id}/objects/ ● GET {api-root}/collections/{id}/objects/{object-id}/ ● GET {api-root}/collections/{id}/objects/{object-id}/versions/ Behaviour of this header on any other endpoint, is not defined.', 'vec_doc-11-oasis-taxii21-p20-66', 0, 295, 'v2.1.0', 'da3f0fe4aa858cc5cc1b680b1b1edf84eb95c66b64470363ef459f415ab14839', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"section 4.1 of [RFC7235].","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":66,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"section 4.1 of [RFC7235]."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p21-67', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.3 Sorting', 21, 'For Object and Manifest Endpoints, objects returned MUST be sorted in ascending order by the date it was added. Meaning, the most recently added object is last in the list. The Collections Endpoint MUST return Collection Resources in a consistent sort order across multiple requests.', 'vec_doc-11-oasis-taxii21-p21-67', 0, 71, 'v2.1.0', '410b7752e38ed3f0716ca633c72876cf51a6cef6c759a8dbe55b28fe7d2093f8', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.3 Sorting","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":67,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.3 Sorting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p21-68', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 21, 'This section defines the URL query parameters used for matching and filtering content. A TAXII Client can request specific content from a TAXII Server by specifying a set of filters included in the request to the server. The URL query parameters listed below specifies what to include in the response from the TAXII Server. If no URL query parameter is specified then the TAXII Client is requesting that all content be returned for that Endpoint, subject to any default behaviors as listed below. If any of the URL query parameters are malformed, the TAXII Server MUST return an HTTP 400 (Bad Request) status code. URL Query Parameters Description added_after A single timestamp that filters objects to only include those objects added after the specified timestamp. The value of this parameter is a timestamp. A request MUST NOT have more than one instance of this URL query parameter. If this parameter is provided it MUST contain only a single timestamp.', 'vec_doc-11-oasis-taxii21-p21-68', 0, 240, 'v2.1.0', '4adbbeae0e64f67d9df044bb11598dca5bd78c0b647efdc26c8a55999b071f3d', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":68,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p21-69', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 21, 'If no added_after URL query parameter is provided, the server MUST return the oldest objects matching the request first. For example, if a server has 100 objects (0-99) and limits requests to 10 objects at a time and a client makes a request without an added_after URL query parameter, the server would start at record 0 looking for a match and work its way up from oldest to newest finding 10 objects that matched the request. The added_after parameter is not in any way related to dates or times in a STIX object or any other CTI object. Note: The HTTP Date header can be used to identify and correct any time skew between client and server. limit A single integer value that indicates the maximum number of objects that the client would like to receive in a single response. ● The value of the limit MUST be a positive integer greater than zero. ● Responses to requests where the client provided a limit MUST NOT contain more objects than requested.', 'vec_doc-11-oasis-taxii21-p21-69', 0, 238, 'v2.1.0', '9dc66541c3056de94e2b1e8d546e89c3f7ce9d236da1c32aa2e5847604aa6a18', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":69,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p21-70', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 21, '● If the number of objects available for the response is less than or equal to both the client requested and server-imposed limit, then all objects MUST be included in the response. ● A response to a request with a defined client limit that is greater than the number of objects that the server is willing or able to provide MAY result in a response with fewer objects than what was requested. ● If more objects are available either because the client requested that they be limited via the limit parameter or the server limited them, then the', 'vec_doc-11-oasis-taxii21-p21-70', 0, 136, 'v2.1.0', 'fae52e519bc1a266dbb87a03e8f890d0c1e07b2711e820ac2952cec896e9dd02', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":70,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p22-71', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 22, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 22 of 79 response envelope MUST have a value of true in the more property and MAY have an appropriate value in the next property. next A single string value that indicates the next record or set of records in the dataset that the client is requesting. A client would get this value from the TAXII Envelope and would use this value along with the original query/filter parameters to paginate through additional records. This value is opaque to clients and may vary between server implementations. match[<field>] The match parameter defines filtering on the specified <field>. The list of fields that MUST be supported is defined per Endpoint as defined in sections 4, 5, and 6. The match parameter can be specified any number of times, where each match instance specifies an additional filter to be applied to the resulting data and each <field> MUST NOT occur more than once in a request.', 'vec_doc-11-oasis-taxii21-p22-71', 0, 250, 'v2.1.0', '0be7428bccd84b65ef563b4450ab559eab8e77d43e146567ef4a0cf3767794f5', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":71,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p22-72', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 22, 'Said another way, all match fields are ANDed together. All <field> parameters are defined in the following table. Requests MAY use a <field> not defined in this specification, and servers MAY ignore fields they do not understand. Each field MAY contain one or more values. Multiple values are separated by a comma (U+002C COMMA, “,”) without any spaces. If multiple values are present, the match is treated as a logical OR. For instance, ?match[type]=incident,malware specifies a filter for objects that are of type incident OR malware. Examples ?match[type]=campaign,malware,threat-actor ?match[type]=incident&match[version]=2016-01-01T01:01:01.000Z 3.4.1 Supported Fields for Match Match Field Description id The identifier of the object(s) that are being requested. When searching for a STIX Object, this is a STIX ID.', 'vec_doc-11-oasis-taxii21-p22-72', 0, 206, 'v2.1.0', '2a758487e3d0fe4bc33b535c10c922fc5aff0940951c3acc6f4f7a07fb1097f5', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":72,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p22-73', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 22, 'Examples ?match[id]=indicator--3600ad1b-fff1-4c98-bcc9-4de3bc2e2ffb ?match[id]=indicator--3600ad1b-fff1-4c98-bcc9-4de3bc2e2ffb,sighting-- 4600ad1b-fff1-4c58-bcc9-4de3bc5e2ffd spec_version The specification version(s) of the STIX object that are being requested. A response to a request with the spec_version match MUST NOT include any specification versions that are not included in this parameter. If no spec_version parameter is provided, the server MUST return only the latest', 'vec_doc-11-oasis-taxii21-p22-73', 0, 120, 'v2.1.0', '2761dee7eb9409bd4c1ffd1f22a871d63899e2d5986c85891fd0d4648983af39', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":73,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p23-74', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 23, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 23 of 79 specification version that it can provide for each object matching the remainder of the request. Examples ?match[spec_version]=2.0 ?match[spec_version]=2.0,2.1 type The type of the object(s) that are being requested. Only the types listed in this parameter are permitted in the response. Requests for types defined in [STIX Version 2.1] MUST NOT result in an error due to an invalid type. Requests for other types not defined in [STIX Version 2.1] MAY be fulfilled. Examples ?match[type]=indicator ?match[type]=indicator,sighting version The version(s) of the object(s) that are being requested from either an object or manifest endpoint. If no version parameter is provided, the server MUST return only the latest version for each object matching the remainder of the request.', 'vec_doc-11-oasis-taxii21-p23-74', 0, 225, 'v2.1.0', '10fd3e3afbc369d681c8249b10c13369de107e1e81f05a621eadb906b5c270da', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":74,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p23-75', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 23, 'If a STIX object is not versioned (and therefore does not have a modified timestamp) then this version parameter MUST use the created timestamp. If an object does not have a created or modified timestamp or any other version information that can be used, then the server should use a value for the version that is consistent to the server. Requests MUST NOT contain any duplicate version parameters, meaning, each keyword (all, first, and last) and any specific version (<value>) MUST NOT occur more than once in a request. However, multiple different specific versions MAY be specified in the same request. Valid values for the version parameter are: ● last  - requests the latest version of an object. This is the default parameter value if no other version parameter is provided. ● first - requests the earliest version of an object. ● all - requests all versions of an object. The all keyword MUST NOT be used with any other version parameter. ● <value> - requests a specific version of an object.', 'vec_doc-11-oasis-taxii21-p23-75', 0, 251, 'v2.1.0', 'ebf242a4585aef80f3e654a05798c068e327ce83e349c45e11f0287ffca533e3', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":75,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p23-76', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 23, '○ For STIX objects, this filter option requests objects whose modified time matches exactly the provided value and the value MUST follow the rules for timestamp as defined in [STIX Version 2.1]. ○ For example: "2016-01-01T01:01:01.000Z" tells the server to return the exact STIX object(s) that matched the modified time of "2016-01-01T01:01:01.000Z".', 'vec_doc-11-oasis-taxii21-p23-76', 0, 88, 'v2.1.0', '85039fc62e95feafb364cecd077dc4a1996cc9731be5bca4cc9903b4aa906668', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":76,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p24-77', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.4 Filtering', 24, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 24 of 79 ○ For non-STIX objects this value MAY, be any string that represents the version of that object type. If the target format does not support object versions, this parameter MUST be ignored. Examples ?match[version]=all ?match[version]=last,first ?match[version]=first,2018-03-02T01:01:01.123Z,last ?match[version]=2016-03-23T01:01:01.000Z,2018-03-02T01:01:01.123Z', 'vec_doc-11-oasis-taxii21-p24-77', 0, 121, 'v2.1.0', 'ea915a41e320eba7bd2cde70e82c94d34424199c5fc600efddbdba2cdbd5df4b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.4 Filtering","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":77,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.4 Filtering"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p24-78', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.5 Pagination', 24, 'TAXII 2.1 supports pagination of large result sets on certain endpoints. These endpoints return results sorted in ascending order by the date they were added to the collection (see section 3.3). The server may limit the number of responses in response to a query, either as the result of a server -specified limit or in response to a limit parameter passed by the client as part of a query (see section 3.4). If more objects are available, either because the client requested that they be limited via the limit parameter or the server limited them, then the response envelope MUST have a value of true in the more property and MAY have an appropriate value in the next property. If the more property is set to true and the next property is populated then the client can paginate through the remaining records using the next URL parameter along with the same original query options.', 'vec_doc-11-oasis-taxii21-p24-78', 0, 221, 'v2.1.0', '62d94625754ed15e59e94d5e8d156001fa4ebc9f2a0b687174da3995cc2255c6', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.5 Pagination","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":78,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.5 Pagination"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p24-79', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.5 Pagination', 24, 'If the more property is set to true and the next property is empty then the client may paginate through the remaining records by using the added_after URL parameter with the date/time value from the X- TAXII-Date-Added-Last header along with the same original query options. It is possible for the server to return "more": true in a response, yet present no additional objects in the follow-on query. This can occur when the additional objects are deleted from a collection between requests. Example: ● Collection High-Value-Indicators has 1000 records in it. ● The client or server has limited all responses to 100 records at a time. ● A client will make a request and the server will respond with the first 100 records. ○ The server will also populate the two X headers for TAXII, X-TAXII-Date-Added-First and X-TAXII-Date-Added-Last. These headers will contain the date/time value of when the first and last records of the 100 returned records were added to the TAXII server.', 'vec_doc-11-oasis-taxii21-p24-79', 0, 245, 'v2.1.0', 'f72c44fe517bc1c6f119f2efa88bc325dde9399ebf2ffd1703033d4c6911cd8c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.5 Pagination","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":79,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.5 Pagination"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p24-80', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.5 Pagination', 24, '○ The server will also set the more property to a value of true and may set the next property to an appropriate value on the TAXII envelope. ● When a client wants to obtain the next 100 records, the client will do either: ○ Provided the same query/filter parameters that it originally used along with populating the next URL parameter with the value from the next property on the previous TAXII envelope response. ○ Or provide the same query/filter parameters that it originally used along with the date/time value from the X-TAXII-Date-Added-Last in the added_after URL parameter', 'vec_doc-11-oasis-taxii21-p24-80', 0, 145, 'v2.1.0', 'ecea61e374a475058e27fc9afc36af5fb528e4c60001918b04038c57e090f712', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.5 Pagination","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":80,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.5 Pagination"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p24-81', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.6 Errors', 24, 'TAXII primarily relies on the standard HTTP error semantics (400-series and 500-series status codes, defined by sections 6.5 and 6.6 of [RFC7231]) to allow TAXII Servers to indicate when an error has', 'vec_doc-11-oasis-taxii21-p24-81', 0, 50, 'v2.1.0', '285f2d65dc505c824d13001391dac302e943b33ab66e6716641aa9fe79d1e7af', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Errors","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":81,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.6 Errors"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p25-82', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.6 Errors', 25, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 25 of 79 occurred. For example, an HTTP 404 (Not Found) status code in response to a request to get information about a Collection means that the Collection could not be found. The tables defining the Endpoint s in sections 4 and 5 identify common errors and which response should be used, but are not exhaustive and do not describe all possible errors. In addition to this, TAXII defines an error message structure that is provided in the response body when an error status is being returned. It does not, however, define any error codes or error conditions beyond those defined by HTTP.', 'vec_doc-11-oasis-taxii21-p25-82', 0, 175, 'v2.1.0', 'b438c4e492c6ba853ed6179caa9a8f550cfae2fe2487be87b3ba5f36ac324f9d', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Errors","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":82,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.6 Errors"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p25-83', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.6 Errors', 25, '3.6.1 Error Message Message Type: error The error message is provided by TAXII Servers in the response body when returning an HTTP error status and contains more information describing the error, including a human-readable title and description, an error_code and error_id, and a details structure to capture further structured information about the error. All of the properties are application-specific, and clients shouldn''t assume consistent meaning across TAXII Servers even if the codes, IDs, or titles are the same. Property Name Type Description title (required) string A human readable plain text title for this error. description (optional) string A human readable plain text description that gives details about the error or problem that was encountered by the application. error_id (optional) string An identifier for this particular error instance. A TAXII Server might choose to assign each error occurrence its own identifier in order to facilitate debugging.', 'vec_doc-11-oasis-taxii21-p25-83', 0, 244, 'v2.1.0', 'ae0f9fd6229421081ccb7254b3e8cc5b97e8b5637eee5afa0609f7d4af677aa7', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Errors","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":83,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.6 Errors"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p25-84', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.6 Errors', 25, 'error_code (optional) string The error code for this error type. A TAXII Server might choose to assign a common error code to all errors of the same type. Error codes are application- specific and not intended to be meaningful across different TAXII Servers. http_status (optional) string The HTTP status code applicable to this error. If this property is provided it MUST match the HTTP status code found in the HTTP header. external_details (optional) string A URL that points to additional details. For example, this could be a URL pointing to a knowledge base article describing the error code. Absence of this property indicates that there are no additional details. details (optional) dictionary The details property captures additional server- specific details about the error. The keys and values are determined by the TAXII Server and MAY be any valid JSON object structure.', 'vec_doc-11-oasis-taxii21-p25-84', 0, 221, 'v2.1.0', 'e99f86cb5d00c382bb8df0b35d4fc9d9561651173bacd3619c1fa14ee27bd630', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Errors","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":84,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.6 Errors"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p26-85', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.6 Errors', 26, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 26 of 79 Examples { "title": "Error condition XYZ", "description": "This error is caused when the application tries to access data...", "error_id": "1234", "error_code": "581234", "http_status": "409", "external_details": "http://example.com/ticketnumber1/errorid-1234", "details": { "somekey1": "somevalue", "somekey2": "some other value" } }', 'vec_doc-11-oasis-taxii21-p26-85', 0, 114, 'v2.1.0', '535f5fce061f84307d85c9adb8085274f04917fa3a66fa508e0e2fe8d8a63e2d', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.6 Errors","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":85,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.6 Errors"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p26-86', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.7 Envelope Resource', 26, 'Resource Name: envelope The envelope is a simple wrapper for STIX 2 content. When returning STIX 2 content in a TAXII response the HTTP root object payload MUST be an envelope. This specification does not define any other form of content wrapper for objects outside of STIX content. For example: ● A single indicator in response to a request for an indicator by ID is enclosed in the objects property list inside of an envelope. ● A list of campaigns returned from a Collection is enclosed in the objects property list inside of an envelope. ● An empty response with no objects property inside the envelope. Property Name Type Description more (optional) boolean This property identifies if there is more content available based on the search criteria. The absence of this property means the value is false. next (optional) string This property identifies the server provided value of the next record or set of records in the paginated data set. This property MAY be populated if the more property is set to true. This value is opaque to the client and represents something that the server knows how to deal with and process.', 'vec_doc-11-oasis-taxii21-p26-86', 0, 282, 'v2.1.0', 'ce64c2d387161ab08c53ffc220aae626b582078363429f027a7417eada0a38ec', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.7 Envelope Resource","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":86,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.7 Envelope Resource"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p27-87', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.7 Envelope Resource', 27, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 27 of 79 For example, for a relational database this could be the index autoID, for elastic search it could be the Scroll ID, for other systems it could be a cursor ID, or it could be any string (or int represented as a string) depending on the requirements of the server and what it is doing in the background. objects (optional) list of type <STIX Object> This property contains one or more STIX Objects. Objects in this list MUST be a STIX Object (e.g., SDO, SCO, SRO, Language Content object, or a Marking Definition object). Examples { "more": true, "next": "123456789", "objects": [ { "type": "indicator", "id": "indicator--252c7c11-daf2-42bd-843b-be65edca9f61", ... } ] }', 'vec_doc-11-oasis-taxii21-p27-87', 0, 198, 'v2.1.0', '8b236701853a269aba270c4098bf0fa027ead701a7313cbe6e7094771e4dc1c9', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.7 Envelope Resource","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":87,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.7 Envelope Resource"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p27-88', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.8 Property Names', 27, '● All property names and string literals MUST be exactly the same, including case, as the names listed in the property tables in this specification. ○ For example, the discovery resource has a property called api_roots and it MUST result in the JSON key name "api_roots". ● Properties marked required in the property tables MUST be present in the JSON serialization of that resource.', 'vec_doc-11-oasis-taxii21-p27-88', 0, 96, 'v2.1.0', '22620fdb100ff967fb5a8488b7fdcea48197ce53afa828440b36cfa9b5e1d2a5', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.8 Property Names","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":88,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.8 Property Names"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p27-89', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.9 DNS SRV Names', 27, 'Organizations that choose to implement a DNS SRV record in their DNS server to advertise the location of their TAXII Server MUST use the service name taxii2. As defined in [RFC2782], the service name is defined without an underscore, and an underscore is added to construct the correct name in the actual DNS SRV record. The protocol for this DNS SRV record MUST be tcp. Examples The following example is for a DNS SRV record advertising a TAXII Server for the domain “example.com” located at taxii-hub-1.example.com:443: _taxii2._tcp.example.com. 86400 IN SRV 0 5 443 taxii-hub-1.example.com', 'vec_doc-11-oasis-taxii21-p27-89', 0, 148, 'v2.1.0', '867a707f414c466dcf81db05b06775e6c49e23c1adec6f8018ea5870788017a8', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.9 DNS SRV Names","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":89,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.9 DNS SRV Names"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p28-90', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3.9 DNS SRV Names', 28, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 28 of 79 4 TAXII API - Server Information The following table provides a summary of the Server Information Endpoints (URLs and HTTP Methods) defined by TAXII and the Resources they operate on. URL Methods Resource Type /taxii2/ GET discovery {api-root}/ GET api-root {api-root}/status/{status-id}/ GET status', 'vec_doc-11-oasis-taxii21-p28-90', 0, 105, 'v2.1.0', 'f9814afc269c5c5f28f1071970d51eb73fda0ac160c1d6aa230f7b08965df98d', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3.9 DNS SRV Names","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":90,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3.9 DNS SRV Names"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p28-91', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.1 Server Discovery', 28, 'This Endpoint provides general information about a TAXII Server, including the advertised API Roots. It''s a common entry point for TAXII Clients into the data and services provided by a TAXII Server. For example, clients auto-discovering TAXII Servers via the DNS SRV record defined in section 1.6.1 will be able to automatically retrieve a discovery response for that server by requesting the /taxii2/ path on that domain. Discovery API responses MAY advertise any TAXII API Root that they have permission to advertise, included those hosted on other servers. GET  /taxii2/ Implementation Notes Get information about the TAXII Server and any advertised API Roots Requests Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers', 'vec_doc-11-oasis-taxii21-p28-91', 0, 205, 'v2.1.0', '398679dfbf78b86c387b4d180819c03db71ea4b7df7f15ffbb2b8025dc464d26', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Server Discovery","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":91,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.1 Server Discovery"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p29-92', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.1 Server Discovery', 29, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 29 of 79 Content-Type: application/taxii+json;version=2.1 Payload discovery Failure Responses Response Codes 401 - The client needs to authenticate 403 - The client does not have access to this resource 404 - The Discovery service is not found, or the client does not have access to the resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /taxii2/ HTTP/1.1 Host: example.com Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 { "title": "Some TAXII Server", "description": "This TAXII Server contains a listing of...", "contact": "string containing contact information", "default": "https://example.com/api2/", "api_roots": [ "https://example.com/api1/", "https://example.com/api2/", "https://example.net/trustgroup1/"', 'vec_doc-11-oasis-taxii21-p29-92', 0, 256, 'v2.1.0', '5bf79292921c82fa71a028c17141dd7c5bc22801441db64b9dac80fcb73ab53b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Server Discovery","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":92,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.1 Server Discovery"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p30-93', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.1 Server Discovery', 30, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 30 of 79 ] } 4.1.1 Discovery Resource Resource Name: discovery The discovery resource contains information about a TAXII Server, such as a human-readable title, description, and contact information, as well as a list of API Roots that it is advertising. It also has an indication of which API Root it considers the default, or the one to use in the absence of another information/user choice. Property Name Type Description title (required) string A human readable plain text name used to identify this server. description (optional) string A human readable plain text description for this server. contact (optional) string The human readable plain text contact information for this server and/or the administrator of this server. default (optional) string The default API Root that a TAXII Client MAY use. Absence of this property indicates that there is no default API Root. The default API Root MUST be an item in api_roots. api_roots (optional) list of type string A list of URLs that identify known API Roots. This list MAY be filtered on a per-client basis. API Root URLs MUST be HTTPS absolute URLs or relative URLs. API Root relative URLs MUST begin with a single `/` character and MUST NOT begin with `//` or ''../". API Root URLs MUST NOT contain a URL query component. Examples - Valid https://taxii.example.com:443/ https://someserver.example.net/apiroot1/ /someapiroot/ Examples -Invalid //someserver.example.com/apiroot1 ../someapiroot/', 'vec_doc-11-oasis-taxii21-p30-93', 0, 391, 'v2.1.0', '16abbf17d37d10a34c0d7d254b856c930eb2885f9455401bb1c08effc1a4f469', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.1 Server Discovery","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":93,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.1 Server Discovery"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p31-94', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.2 Get API Root Information', 31, 'This Endpoint provides general information about an API Root, which can be used to help users and clients decide whether and how they want to interact with it. Multiple API Roots MAY be hosted on a single TAXII Server. Often, an API Root represents a single trust group. ● Each API Root MUST have a unique URL. ● Each API Root MAY have different authentication and authorization schemes. GET  /{api-root}/ Implementation Notes Get information about a specific API Root Requests URL Parameters {api-root} - the base URL of the API Root Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 Payload api-root Failure Responses Response Codes', 'vec_doc-11-oasis-taxii21-p31-94', 0, 195, 'v2.1.0', '45d824e29de8fdbfff8ffa9ea00464f10ac336cfda76d5e0575c0c10bf8b39fb', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Get API Root Information","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":94,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.2 Get API Root Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p32-95', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.2 Get API Root Information', 32, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 32 of 79 401 - The client needs to authenticate 403 - The client does not have access to this resource 404 - The API Root is not found, or the client does not have access to the resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /api1/ HTTP/1.1 Host: example.com Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 { "title": "Malware Research Group", "description": "A trust group setup for malware researchers", "versions": ["application/taxii+json;version=2.1"], "max_content_length": 104857600 } 4.2.1 API Root Resource Resource Name: api-root The api-root resource contains general information about the API Root, such as a human-readable title and description, the TAXII versions it supports, and the maximum size (max_content_length) of the content body it will accept in a PUT or POST request. Property Name Type Description', 'vec_doc-11-oasis-taxii21-p32-95', 0, 285, 'v2.1.0', 'a6440fc08a82adaeb059c26a8959be92d3f777a2029f03daca511f2654d49ed6', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Get API Root Information","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":95,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.2 Get API Root Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p33-96', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.2 Get API Root Information', 33, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 33 of 79 title (required) string A human readable plain text name used to identify this API instance. description (optional) string A human readable plain text description for this API Root. versions (required) list of type string The list of TAXII versions that this API Root is compatible with. The values listed in this property MUST match the media types defined in Section 1.6.8.1 and MUST include the optional version parameter. A value of "application/taxii+json;version=2.1" MUST be included in this list to indicate conformance with this specification. max_content_length (required) integer The maximum size of the request body in octets (8-bit bytes) that the server can support. The value of the max_content_length MUST be a positive integer greater than zero. This applies to requests only and is determined by the server. Requests with total body length values smaller than this value MUST NOT result in an HTTP 413 (Request Entity Too Large) response. If for example, the server supported 100 MB of data, the value for this property would be determined by 100*1024*1024 which equals 104,857,600. This property contains useful information for the client when it POSTs requests to the Add Objects endpoint.', 'vec_doc-11-oasis-taxii21-p33-96', 0, 333, 'v2.1.0', '49fef491887f751a12965ad7086ef5c1ab58bcfc64586456e3f2ce0e590784a6', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.2 Get API Root Information","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":96,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.2 Get API Root Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p33-97', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 33, 'This Endpoint provides information about the status of a previous request. In TAXII 2.1, the only request that can be monitored is one to add objects to a Collection (see section 5.5). It is typically used by TAXII Clients to monitor a POST request that they made in order to take action when it is complete. TAXII Servers SHOULD accept queries for a given status ID for at least 24 hours after the server has finished processing the request. Once a TAXII client receives a status resource where the status value is complete for a given status ID it SHOULD never pull for that status ID again. If the TAXII Server receives a request on the status endpoint for a status ID that is no longer available , the server MUST return an HTTP status of 404 (Not Found). GET  /{api-root}/status/{status-id}/ Implementation Notes Get status information for a specific status ID Requests', 'vec_doc-11-oasis-taxii21-p33-97', 0, 219, 'v2.1.0', '4ae4477e691c2603e31e6c488529f92a842708e6036f93b4e74fd939ff96ea7e', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":97,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p34-98', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 34, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 34 of 79 URL Parameters {api-root}  - the base URL of the API Root {status-id} - the identifier of the status message being requested Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 Payload status Failure Responses Response Codes 401 - The client needs to authenticate 403 - The client does not have access to this resource 404 - The API Root or Status ID are not found, or the client does not have access to the resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /api1/status/2d086da7-4bdc-4f91-900e-d77486753710/ HTTP/1.1 Host: example.com', 'vec_doc-11-oasis-taxii21-p34-98', 0, 231, 'v2.1.0', 'b46cf8ab9e1a8c895838a5ac2d58b6b82079741549e32b63404b59b246a83c4a', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":98,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p35-99', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 35, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 35 of 79 Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 { "id": "2d086da7-4bdc-4f91-900e-d77486753710", "status": "pending", "request_timestamp": "2016-11-02T12:34:34.12345Z", "total_count": 4, "success_count": 1, "successes": [ { "id": "indicator--c410e480-e42b-47d1-9476-85307c12bcbf" , "version": "2018-05-27T12:02:41.312Z" } ], "failure_count": 1, "failures": [ { "id": "malware--664fa29d-bf65-4f28-a667-bdb76f29ec98", "version": "2018-05-28T14:03:42.543Z", "message": "Unable to process object" } ], "pending_count": 2, "pendings": [ { "id": "indicator--252c7c11-daf2-42bd-843b-be65edca9f61", "version": "2018-05-18T20:16:21.148Z" }, { "id": "relationship--045585ad-a22f-4333-af33-bfd503a683b5", "version": "2018-05-15T10:13:32.579Z" } ] }', 'vec_doc-11-oasis-taxii21-p35-99', 0, 233, 'v2.1.0', '3d23e30eabc948c3d50f828442804cba7e727f7d592675c72e1ab1794771f448', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":99,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p36-100', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 36, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 36 of 79 4.3.1 Status Resource Resource Name: status The status resource represents information about a request to add objects to a Collection. It contains information about the status of the request, such as whether or not it''s completed (status) and MAY contain the status of individual objects within the request (i.e. whether they are still pending, completed and failed, or completed and succeeded). The status resource is returned in two places: as a response to the initial POST request (see section 5.5) and in response to a get status request (see section 4.3), which can be made after the initial request to continuously monitor its status.', 'vec_doc-11-oasis-taxii21-p36-100', 0, 191, 'v2.1.0', 'edcd1da8e8cb82f2b33951160e49a8ed5c4f8b286979bc086c9a6b47df4e1451', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":100,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p36-101', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 36, 'The list of objects that failed to be added, are still pending, or have been successfully added is a simple type, named status-details, that contains the identifier of the object (e.g., for STIX objects, their id), its version, and an optional  message indicating additional details. Property Name Type Description id (required) identifier The identifier of this Status resource. status (required) string The overall status of a previous POST request where an HTTP 202 (Accept) was returned. The value of this property MUST be one of complete or pending. A value of complete indicates that this resource will not be updated further, and MAY be removed in the future. A status of pending indicates that this resource MAY be updated in the future. request_timestamp (optional) timestamp The datetime of the request that this status resource is monitoring. total_count (required) integer The total number of objects that were in the request, which would be the number of objects in the envelope.', 'vec_doc-11-oasis-taxii21-p36-101', 0, 248, 'v2.1.0', '52172fe70f1376f90fb14c13569936e474488590b20e57392b064a90ad2f007c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":101,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p36-102', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 36, 'The value of the total_count MUST be a positive integer greater than or equal to zero. If this property has a value of 0, then the TAXII Server has not yet started processing the request. success_count (required) integer The number of objects that were successfully created. The value of the success_count MUST be a positive integer greater than or equal to zero. successes (optional) list of type status-details A list of objects that was successfully processed.', 'vec_doc-11-oasis-taxii21-p36-102', 0, 116, 'v2.1.0', '2cda8809426bbfa7166f4ae91d75e88759b6725a0902231a5d0e76e847f151da', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":102,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p37-103', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 37, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 37 of 79 failure_count (required) integer The number of objects that failed to be created. The value of the failure_count MUST be a positive integer greater than or equal to zero. failures (optional) list of type status-details A list of objects that was not successfully processed. pending_count (required) integer The number of objects that have yet to be processed. The value of the pending_count MUST be a positive integer greater than or equal to zero. pendings (optional) list of type status-details A list of objects that have yet to be processed. Type Name: status-details This type represents an object that was added, is pending, or not added to the Collection. It contains the id and version of the object along with a message describing any details about its status.', 'vec_doc-11-oasis-taxii21-p37-103', 0, 223, 'v2.1.0', '4bf359099fdd1399d5314234848127c201834a3a563d6dabf9bd40e9cb27fc6b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":103,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p37-104', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 37, 'Property Name Type Description id (required) string The identifier of the object that succeed, is pending, or failed to be created. For STIX objects the id MUST be the STIX Object id. For object types that do not have their own identifier, the server MAY use any value as the id. version (required) string The version of the object that succeeded, is pending, or failed to be created. For STIX objects the version MUST be the STIX modified timestamp Property. If a STIX object is not versioned (and therefore does not have a modified timestamp), the server MUST use the created timestamp. If the STIX object does not have a created or modified timestamp then the server SHOULD use a value for the version that is consistent to the server. message (optional) string A message indicating more information about the object being created, its pending state, or why the object failed to be created.', 'vec_doc-11-oasis-taxii21-p37-104', 0, 224, 'v2.1.0', 'acc3c46a38b9b0a9369eedae64778526091ad01219333cd54409e4d6456a042a', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":104,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p37-105', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 37, 'Status URL Examples https://example.com/api1/status/2d086da7-4bdc-4f91-900e-d77486753710/ https://example.com/api2/status/88dc8293-827e-44f0-a592-4b5302fbe9d3/', 'vec_doc-11-oasis-taxii21-p37-105', 0, 40, 'v2.1.0', 'c02ce6475fe42b9e2152f7f1c753150f4f2ed6cedab9fc5ac5d45b713d138df6', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":105,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p39-106', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4.3 Get Status', 39, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 39 of 79 5 TAXII API - Collections A TAXII Collection is a logical grouping of threat intelligence that enables the exchange of information between a TAXII Client and a TAXII Server in a request-response manner. Collections are hosted in the context of an API Root. Each API Root MAY have zero or more Collections. As with other TAXII Endpoints, the ability of TAXII Clients to read from and write to Collections can be restricted depending on their permissions level. This section defines the TAXII API Collection Endpoints (URLs and methods), va lid media types, and responses. The following table provides a summary of the Endpoints (URLs and HTTP Methods) defined by TAXII and the Resources they operate on. URL Methods Resource Type {api-root}/collections/ GET collections {api-root}/collections/{id}/ GET collection {api-root}/collections/{id}/manifest/ GET manifest {api-root}/collections/{id}/objects/ GET, POST envelope {api-root}/collections/{id}/objects/{object-id}/ GET, DELETE envelope {api-root}/collections/{id}/objects/{object-id}/versions/ GET versions', 'vec_doc-11-oasis-taxii21-p39-106', 0, 296, 'v2.1.0', '70862e144079816223462a6abd95f0529c1a60abb1661fc1534ac1c646c91966', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4.3 Get Status","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":106,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4.3 Get Status"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p39-107', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.1 Get Collections', 39, 'This Endpoint provides information about the Collections hosted under this API Root. This is similar to the response to get a Collection (see section 5.2), but rather than providing information about one Collection it provides information about all of the Collections. Most importantly, it provides the Collection''s id, which is used to request objects or manifest entries from the Collection. If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found). GET  /{api-root}/collections/ Implementation Notes Get information about all collections', 'vec_doc-11-oasis-taxii21-p39-107', 0, 152, 'v2.1.0', 'cccdb0fd0119d998c41b40cdc5ea86611602d0bdb8654de4a8a754e95c84ceac', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Get Collections","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":107,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.1 Get Collections"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p40-108', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.1 Get Collections', 40, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 40 of 79 Requests URL Parameters {api-root} - the base URL of the API Root Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 Payload collections Failure Responses Response Codes 400 - The server did not understand the request 401 - The client needs to authenticate 403 - The client does not have access to this collections resource 404 - The API Root is not found, or the client does not have access to the collections resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /api1/collections/ HTTP/1.1', 'vec_doc-11-oasis-taxii21-p40-108', 0, 220, 'v2.1.0', '32a739d4882ddc2f78d6cd9d7fc2c77a3bc4fff7190e54f669bbe68b3799ec1a', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Get Collections","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":108,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.1 Get Collections"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p41-109', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.1 Get Collections', 41, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 41 of 79 Host: example.com Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 { "collections": [ { "id": "91a7b528-80eb-42ed-a74d-c6fbd5a26116", "title": "High Value Indicator Collection", "description": "This data collection contains high value IOCs", "can_read": true, "can_write": false, "media_types": [ "application/stix+json;version=2.1" ] }, { "id": "52892447-4d7e-4f70-b94d-d7f22742ff63", "title": "Indicators from the past 24-hours", "description": "This data collection is for collecting current IOCs", "can_read": true, "can_write": false, "media_types": [ "application/stix+json;version=2.1" ] } ] } 5.1.1 Collections Resource Resource Name: collections The collections resource is a simple wrapper around a list of collection resources. Property Name Type Description', 'vec_doc-11-oasis-taxii21-p41-109', 0, 241, 'v2.1.0', '844d0fe58db62381632e2212ef5dc2f6fc1fe59454c8542d1cb9b18fda0a397b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.1 Get Collections","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":109,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.1 Get Collections"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p42-110', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.2 Get a Collection', 42, 'This Endpoint provides general information about a Collection, which can be used to help users and clients decide whether and how they want to interact with it. For example, it will tell clients what it''s called and what permissions they have to it. If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found). GET  /{api-root}/collections/{id}/ Implementation Notes Get information about a specific collection Requests URL Parameters {api-root} - the base URL of the API Root {id}       - the identifier of the Collection being requested Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 Payload collection', 'vec_doc-11-oasis-taxii21-p42-110', 0, 205, 'v2.1.0', '815e25c5a12373f6cfc3ac3ed7b31f36b8d3dfda260a21d8c1bb10b7eae59824', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Get a Collection","subsection":"UNKNOWN","table_id":null,"page":42,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":110,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.2 Get a Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p43-111', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.2 Get a Collection', 43, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 43 of 79 Failure Responses Response Codes 400 - The server did not understand the request 401 - The client needs to authenticate 403 - The client does not have access to this collection resource 404 - The API Root or Collection ID are not found, or the client does not have access to the collection resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /api1/collections/91a7b528-80eb-42ed-a74d-c6fbd5a26116/ HTTP/1.1 Host: example.com Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 { "id": "91a7b528-80eb-42ed-a74d-c6fbd5a26116", "title": "High Value Indicator Collection", "description": "This data collection contains high value IOCs", "can_read": true, "can_write": false, "media_types": [ "application/stix+json;version=2.1" ] }', 'vec_doc-11-oasis-taxii21-p43-111', 0, 260, 'v2.1.0', 'fe0f47bded81fd10a590e278292a8b80afd872b84b23714f897f80b1ddac9e0c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Get a Collection","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":111,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.2 Get a Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p44-112', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.2 Get a Collection', 44, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 44 of 79 5.2.1 Collection Resource Resource Name: collection The collection resource contains general information about a Collection, such as its id, a human- readable title and description, an optional list of supported media_types (representing the media type of objects can be requested from or added to it), and whether the TAXII Client, as authenticated, can get objects from the Collection and/or add objects to it. Property Name Type Description id (required) identifier The id property universally and uniquely identifies this Collection. It is used in the Get Collection Endpoint (see section 5.2) as the {id} parameter to retrieve the Collection. title (required) string A human readable plain text title used to identify this Collection. description (optional) string A human readable plain text description for this Collection.', 'vec_doc-11-oasis-taxii21-p44-112', 0, 238, 'v2.1.0', 'd101083c2529bfe018a0f728fdb1e44c768e481d70064408bc9e6ad69fbb3165', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Get a Collection","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":112,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.2 Get a Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p44-113', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.2 Get a Collection', 44, 'alias (optional) string A human readable collection name that can be used on systems to alias a collection ID. This could be used by organizations that want to preconfigure a known collection of data, regardless of the underlying collection ID that is configured on a specific implementations. If defined, the alias MUST be unique within a single api-root on a single TAXII server. There is no guarantee that an alias is globally unique across api- roots or TAXII server instances. Example: /{api-root}/collections/critical-high-value- indicators/ can_read (required) boolean Indicates if the requester can read (i.e., GET) objects from this Collection. If true, users are allowed to access the Get Objects, Get an Object, or Get Object Manifests endpoints for this Collection. If false, users are not allowed to access these endpoints. can_write (required) boolean Indicates if the requester can write (i.e., POST) objects to this Collection.', 'vec_doc-11-oasis-taxii21-p44-113', 0, 236, 'v2.1.0', '0a6991670649d60bf3b78a2bcbfaf6c16f537f281a309bf1a61ffb22837988c6', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Get a Collection","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":113,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.2 Get a Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p44-114', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.2 Get a Collection', 44, 'If true, users are allowed to access the Add Objects endpoint for this Collection. If false, users are not allowed to access this endpoint. media_types (optional) list of type A list of supported media types for Objects in this', 'vec_doc-11-oasis-taxii21-p44-114', 0, 57, 'v2.1.0', 'fa1c189066b151c57223ee08618c9be4dc0fe7cb0d66ef456dbd814149995612', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.2 Get a Collection","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":114,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.2 Get a Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p45-115', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.3 Get Object Manifests', 45, 'This Endpoint retrieves a manifest about the objects in a Collection. It supports filtering identical to the get objects Endpoint (see section 5.4) but rather than returning the object itself it returns metadata about the object. It can be used to retrieve metadata to decide whether it''s worth retrieving the actual objects. If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found). If the Collection specifies can_read as false for a particular client, this Endpoint MUST return an HTTP HTTP 403 (Forbidden) or HTTP 404 (Not Found) error. Filtering is applied against the source object rather than the manifest entry for an obje ct. Thus, searching the manifest for a type of indicator will return the manifest entries for objects with a type of indicator, even though the manifest doesn''t have a type property. If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found). GET  /{api-root}/collections/{id}/manifest/ Implementation Notes Get manifest information about the contents of a specific collection. Requests URL Parameters {api-root}  - the base URL of the API Root {id}        - the identifier of the Collection being requested URL Filtering Parameters added_after  - a single timestamp            (e.g., ?added_after=...) limit        - a single integer              (e.g., ?limit=...) next         - a single string               (e.g., ?next=...) id           - an id(s) of an object         (e.g., ?match[id]=...) type         - the type(s) of an object      (e.g., ?match[type]=...) version      - the version(s) of an object   (e.g., ?match[version]=...) spec_version - the specification version(s)  (e.g., ?match[spec_version]=...)', 'vec_doc-11-oasis-taxii21-p45-115', 0, 446, 'v2.1.0', '73d0817864f6ccd588f8bf982525723cb79cc6b39b89bd22ce0f9a5f57f2ec87', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.3 Get Object Manifests","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":115,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.3 Get Object Manifests"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p46-116', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.3 Get Object Manifests', 46, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 46 of 79 Filtering is based on properties of the objects that the manifest entries represent. For example, filtering by type=indicator will return manifest entries for objects with a type of indicator. Required Headers Accept: application/taxii+json;version=2.1,application/stix+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 X-TAXII-Date-Added-First: timestamp X-TAXII-Date-Added-Last: timestamp Payload manifest Failure Responses Response Codes 400 - The server did not understand the request or filter parameters 401 - The client needs to authenticate 403 - The client does not have access to this manifest resource 404 - The API Root or Collection ID are not found, or the client does not have access to the manifest resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /api1/collections/91a7b528-80eb-42ed-a74d-c6fbd5a26116/manifest/ HTTP/1.1', 'vec_doc-11-oasis-taxii21-p46-116', 0, 297, 'v2.1.0', 'e32e6d5fb77c54b70f0be882eda38f48131a05eb5dac47ef869a1b78aa2d9f48', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.3 Get Object Manifests","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":116,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.3 Get Object Manifests"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p47-117', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.3 Get Object Manifests', 47, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 47 of 79 Host: example.com Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 X-TAXII-Date-Added-First: timestamp X-TAXII-Date-Added-Last: timestamp { "objects": [ { "id": "indicator--29aba82c-5393-42a8-9edb-6a2cb1df070b", "date_added": "2016-11-04T03:04:051Z", "version": "2016-11-03T12:30:59.000Z", "media_type": "application/stix+json;version=2.1" }, { "id": "indicator--ef0b28e1-308c-4a30-8770-9b4851b260a5", "date_added": "2016-11-04T10:29:061Z", "version": "2016-11-03T12:35:10.000Z", "media_type": "application/stix+json;version=2.1" } ] } 5.3.1 Manifest Resource Resource Name: manifest The manifest resource is a simple wrapper around a list of manifest-record items. Property Name Type Description more (optional) boolean This property identifies if there is more content available based on the search criteria. The absence of this property means the value is false. objects (optional) list of type manifest-record The list of manifest entries for objects returned by the request. If there are no manifest-record items in the list, this key MUST be omitted, and', 'vec_doc-11-oasis-taxii21-p47-117', 0, 314, 'v2.1.0', 'ba21cb837e42cac5e8f8321785de244ea77ebfa5a6799007d34add0dd50c0fe3', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.3 Get Object Manifests","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":117,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.3 Get Object Manifests"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p48-118', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.3 Get Object Manifests', 48, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 48 of 79 the response is an empty object. Type Name: manifest-record The manifest-record type captures metadata about a single version of an object, indicated by the id property. The metadata includes information such as when that version of the object was added to the Collection, the version of the object itself, and the media type that this specific version of the object is available in. Property Name Type Description id (required) string The identifier of the object that this manifest entry describes. For STIX objects the id MUST be the STIX Object id. For object types that do not have their own identifier, the server MAY use any value as the id. date_added (required) timestamp The date and time this object was added. version (required) string The version of this object. For objects in STIX format, the STIX modified property is the version. If a STIX object is not versioned (and therefore does not have a modified timestamp), the server MUST use the created timestamp. If the STIX object does not have a created or modified timestamp then the server SHOULD use a value for the version that is consistent to the server. media_type (optional) string The media type that this specific version of the object can be requested in. This value MUST be one of the media types listed on the collection resource.', 'vec_doc-11-oasis-taxii21-p48-118', 0, 358, 'v2.1.0', '0fd01b157c15051c39a3ff7ccd82b40a5adf8716523f8e5be16f12483cc59ebd', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.3 Get Object Manifests","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":118,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.3 Get Object Manifests"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p48-119', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.4 Get Objects', 48, 'This Endpoint retrieves objects from a Collection. Clients can search for objects in the Collection, retrieve all objects in a Collection, or paginate through objects in the Collection. Pagination is supported by the limit URL query parameter (see section 3.4) and the more property of the envelope (see section 3.7). If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found) If the Collection specifies can_read as false for a particular client, this Endpoint MUST return an HTTP HTTP 403 (Forbidden) or HTTP 404 (Not Found) error. To support searching the Collection, this Endpoint supports filtering as defined in section 3.4. Clients can provide one or more filter parameters to get objects with a specific ID, of a specific type, or with a specific version. Future versions of TAXII will add more advanced filtering capabilities.', 'vec_doc-11-oasis-taxii21-p48-119', 0, 226, 'v2.1.0', '4bd733adb92c63e29ee151f548f84c83e84ae6bc927414226dcf534e52cf2b01', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.4 Get Objects","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":119,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.4 Get Objects"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p49-120', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.4 Get Objects', 49, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 49 of 79 When requesting STIX 2 content, that content will always be delivered in a TAXII envelope even if there only one object returned. If no STIX objects are returned, the response MUST include an empty envelope. An envelope is returned even when requesting a specific object ID, as there may be multiple versions of that object that are returned. GET  /{api-root}/collections/{id}/objects/ Implementation Notes Get all objects from a collection Requests URL Parameters {api-root} - the base URL of the API Root {id}       - the identifier of the Collection being requested URL Filtering Parameters added_after  - a single timestamp            (e.g., ?added_after=...) limit        - a single integer              (e.g., ?limit=...) next         - a single string               (e.g., ?next=...) id           - an id(s) of an object         (e.g., ?match[id]=...) type         - the type(s) of an object      (e.g., ?match[type]=...) version      - the version(s) of an object   (e.g., ?match[version]=...) spec_version - the specification version(s)  (e.g., ?match[spec_version]=...) Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 X-TAXII-Date-Added-First: timestamp X-TAXII-Date-Added-Last: timestamp', 'vec_doc-11-oasis-taxii21-p49-120', 0, 367, 'v2.1.0', '593223d9307f894bc62123f44f9f317fcbb0de21c37929845140dcc76a761bc8', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.4 Get Objects","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":120,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.4 Get Objects"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p50-121', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.4 Get Objects', 50, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 50 of 79 Payload envelope Failure Responses Response Codes 400 - The server did not understand the request or filter parameters 401 - The client needs to authenticate 403 - The client does not have access to this objects resource 404 - The API Root or Collection ID are not found, or the client does not have access to the objects resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /api1/collections/91a7b528-80eb-42ed-a74d-c6fbd5a26116/objects/ HTTP/1.1 Host: example.com Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 X-TAXII-Date-Added-First: timestamp X-TAXII-Date-Added-Last: timestamp { "objects": [ { "type": "indicator", ... } ] }', 'vec_doc-11-oasis-taxii21-p50-121', 0, 237, 'v2.1.0', '4cb759c97bc9f9b53b8c712b1c3b762c0ade109c733b30218fd4a2dde0f8a457', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.4 Get Objects","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":121,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.4 Get Objects"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p51-122', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.5 Add Objects', 51, 'This Endpoint adds objects to a Collection. If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found). If the Collection specifies can_write as false for a particular client, this Endpoint MUST return an HTTP HTTP 403 (Forbidden) or HTTP 404 (Not Found) error. Successful responses to this Endpoint will contain a status resource describing the status of the request. The status resource contains an id, which can be used to make requests to the get  status Endpoint (see section 4.3), a status flag to indicate whether the request is completed or still being processed, and information about the status of the particular objects in the request. If a client publishes an exact duplicate of an Object already present in the Collection, the server MUST not return an error for that Object. If the request is marked pending in the status property, the client SHOULD periodically poll the get status Endpoint to get an updated status until such a time that the status property returns a value of complete. At that point, the request can be considered complete. When adding STIX 2 content, clients MUST deliver all objects in a TAXII envelope. POST  /{api-root}/collections/{id}/objects/ Implementation Notes Add a new object to a specific collection Requests URL Parameters {api-root} - the base URL of the API Root {id}       - the identifier of the Collection where objects are being added Required Headers Accept: application/taxii+json;version=2.1 Content-Type: application/taxii+json;version=2.1 Payload envelope Successful Responses Response Codes 202 - The request was successful accepted', 'vec_doc-11-oasis-taxii21-p51-122', 0, 415, 'v2.1.0', 'c98fd41beba588ac2ea733bacf0b570b41befc53f384ae47c4323113de046e69', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.5 Add Objects","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":122,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.5 Add Objects"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p52-123', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.5 Add Objects', 52, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 52 of 79 Required Headers Content-Type: application/taxii+json;version=2.1 Payload status Failure Responses Response Codes 400 - The server did not understand the request 401 - The client needs to authenticate 403 - The client does not have access to write to this objects resource 404 - The API Root or Collection ID are not found, or the client can not write to this objects resource 406 - The media type provided in the Accept header is invalid 413 - The POSTed payload exceeds the max_content_length of the API Root 415 - The client attempted to POST a payload with a content type the server does not support 422 - The object type or version is not supported or could not be processed. This can happen, for example, when sending a version of STIX that this TAXII Server does not support and cannot process, when sending a malformed body, or other unprocessable content Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example POST Request POST /api1/collections/91a7b528-80eb-42ed-a74d-c6fbd5a26116/objects/ HTTP/1.1 Host: example.com Accept: application/taxii+json;version=2.1 Content-Type: application/taxii+json;version=2.1 { "objects": [', 'vec_doc-11-oasis-taxii21-p52-123', 0, 322, 'v2.1.0', '132bee053c8fd04ce30e7fc35f98952b851c1014da9e64f22f2d68d3ebbca95d', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.5 Add Objects","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":123,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.5 Add Objects"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p53-124', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.5 Add Objects', 53, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 53 of 79 { "type": "indicator", "id": "indicator--c410e480-e42b-47d1-9476-85307c12bcbf", ... } ] } POST Response HTTP/1.1 202 Accepted Content-Type: application/taxii+json;version=2.1 { "id": "2d086da7-4bdc-4f91-900e-d77486753710", "status": "pending", "request_timestamp": "2016-11-02T12:34:34.12345Z", "total_count": 4, "success_count": 1, "successes": [ { "id": "indicator--c410e480-e42b-47d1-9476-85307c12bcbf" } ], "failure_count": 0, "pending_count": 3 }', 'vec_doc-11-oasis-taxii21-p53-124', 0, 143, 'v2.1.0', '33f2f8a5e9f2ac87062632604895ec67c5547ec2978f2859ab3a7830424aaeee', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.5 Add Objects","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":124,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.5 Add Objects"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p53-125', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.6 Get an Object', 53, 'This Endpoint gets an object from a Collection by its id. It can be thought of as a search where the match[id] parameter is set to the {object-id} in the path. For STIX 2 objects, the {object-id} MUST be the STIX id. If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found). If the Collection specifies can_read as false for a particular client, this Endpoint MUST return an HTTP HTTP 403 (Forbidden) or HTTP 404 (Not Found) error. To support getting a particular version of an object, this Endpoint supports filtering as defined in section 3.4. The only valid match parameter is version. When requesting STIX 2 content, that content will always be delivered in a TAXII envelope even if there only one object returned. If no STIX objects are returned, the response MUST include an empty envelope. An envelope is returned even when requesting a specific object ID, as there may be multiple versions of that object that are returned.', 'vec_doc-11-oasis-taxii21-p53-125', 0, 250, 'v2.1.0', '18b5082027e9e8ab22394dfa9346f8f670f8b502602398d4c3c0a58c093bda47', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.6 Get an Object","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":125,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.6 Get an Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p54-126', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.6 Get an Object', 54, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 54 of 79 GET  /{api-root}/collections/{id}/objects/{object-id}/ Implementation Notes Get a specific object from a collection Requests URL Parameters {api-root}  - the base URL of the API Root {id}        - the identifier of the Collection being requested {object-id} - the ID of the object being requested URL Filtering Parameters added_after  - a single timestamp            (e.g., ?added_after=...) limit        - a single integer              (e.g., ?limit=...) next         - a single string               (e.g., ?next=...) version      - the version(s) of an object   (e.g., ?match[version]=...) spec_version - the specification version(s)  (e.g., ?match[spec_version]=...) Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 X-TAXII-Date-Added-First: timestamp X-TAXII-Date-Added-Last: timestamp Payload envelope Failure Responses', 'vec_doc-11-oasis-taxii21-p54-126', 0, 273, 'v2.1.0', '90315a2786b3c8ce04c2adcd0ca09ef35b1f0bcc95dabe6687b8812d7b2c6366', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.6 Get an Object","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":126,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.6 Get an Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p55-127', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.6 Get an Object', 55, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 55 of 79 Response Codes 400 - The server did not understand the request or filter parameters 401 - The client needs to authenticate 403 - The client does not have access to this object resource 404 - The API Root, Collection ID and/or Object ID are not found, or the client does not have access to the object resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /api1/collections/91a7b528-80eb-42ed-a74d-c6fbd5a26116/object/ indicator--252c7c11-daf2-42bd-843b-be65edca9f61/ HTTP/1.1 Host: example.com Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 X-TAXII-Date-Added-First: timestamp X-TAXII-Date-Added-Last: timestamp { "objects": [ { "type": "indicator", "id": "indicator--252c7c11-daf2-42bd-843b-be65edca9f61", ..., } ] }', 'vec_doc-11-oasis-taxii21-p55-127', 0, 258, 'v2.1.0', '787b845f75c336e1001d7426bae73a39cd3694e11d9cc42e5fa3421ceba09b0c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.6 Get an Object","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":127,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.6 Get an Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p56-128', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.7 Delete an Object', 56, 'This Endpoint deletes an object from a Collection by its id. For STIX 2 objects, the {object-id} MUST be the STIX id. To support removing a particular version of an object, this Endpoint supports filtering as defined in section 3.4. The only valid match parameter is version. When a TAXII Server returns a successful response code of 200 to a DELETE, any subsequent attempts to fetch that object/version from the collection by an authorized client using the Get Objects Endpoint MUST return an HTTP 404 (Not Found) response. Furthermore, any subsequent attempts to fetch the collection manifest or its contents MUST NOT return the object in the result. Subsequent attempts to fetch the object from other collections present on the TAXII server MAY also return an HTTP 404 (Not Found) response, and subsequent attempts to fetch the collection manifest or its contents of other collections which contained the object MAY not return the object in the result.', 'vec_doc-11-oasis-taxii21-p56-128', 0, 239, 'v2.1.0', '18af0b6a9acc10e9ea82961fc2ed70e7ffe1d80a7198c37e956e117caa70975b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.7 Delete an Object","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":128,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.7 Delete an Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p56-129', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.7 Delete an Object', 56, 'If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found). The following table defines the conditions and error codes that can be returned once a client has successfully authenticated to this endpoint. If the collection specifies the following permissions for the authenticated client and the client attempts to delete an object at this endpoint, then this endpoint MUST return the error codes as defined in the following table. NOTE, the DELETE endpoint is only supported for collections where both can_read is true and can_write is true. Client can_read Client can_write Mandatory Responses false false HTTP 404 (Not Found) true false HTTP 403 (Forbidden) false true HTTP 403 (Forbidden) true true < See the Successful and Failure Response sections below > DELETE  /{api-root}/collections/{id}/objects/{object-id}/ Implementation Notes Delete a specific object from a collection Requests URL Parameters', 'vec_doc-11-oasis-taxii21-p56-129', 0, 243, 'v2.1.0', '998b3aa90a5b46fe033581a90f3e475405af5c630e9708566773a5c5636034a5', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.7 Delete an Object","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":129,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.7 Delete an Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p57-130', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.7 Delete an Object', 57, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 57 of 79 {api-root}  - the base URL of the API Root {id}        - the identifier of the Collection being requested {object-id} - the ID of the object being deleted URL Filtering Parameters version      - the version(s) of an object   (e.g., ?match[version]=...) spec_version - the specification version(s)  (e.g., ?match[spec_version]=...) Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 Payload n/a Failure Responses Response Codes 400 - The server did not understand the request 401 - The client needs to authenticate 403 - The client has access to the object, but not to delete it 404 - The API Root, Collection ID and/or Object ID are not found, or the client does not have access to the object 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example', 'vec_doc-11-oasis-taxii21-p57-130', 0, 277, 'v2.1.0', '0ed65eea52e2812ace27b90b1bda2d7d3990600c9851adbba8900397d0bfaab7', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.7 Delete an Object","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":130,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.7 Delete an Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p58-131', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.7 Delete an Object', 58, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 58 of 79 DELETE Request DELETE /api1/collections/91a7b528-80eb-42ed-a74d-c6fbd5a26116/object/ indicator--252c7c11-daf2-42bd-843b-be65edca9f61/ HTTP/1.1 Host: example.com Accept: application/taxii+json;version=2.1 DELETE Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1', 'vec_doc-11-oasis-taxii21-p58-131', 0, 102, 'v2.1.0', '4c6221632d9113c355357c5e1737c4003daa082714b19cba98789cb17162428d', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.7 Delete an Object","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":131,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.7 Delete an Object"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p58-132', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.8 Get Object Versions', 58, 'This Endpoint retrieves a list of one or more versions of an object in a Collection. This list can be used to decide whether it''s worth retrieving the actual objects, or if new versions have been added. If a STIX object is not versioned (and therefore does not have a modified timestamp), the server MUST use created timestamp. If a client fails authentication then this endpoint MUST return either an HTTP 401 (Unauthorized) or an HTTP 404 (Not Found). If the Collection specifies can_read as false for a particular client, this Endpoint MUST return an HTTP HTTP 403 (Forbidden) or HTTP 404 (Not Found) error. GET  /{api-root}/collections/{id}/objects/{object-id}/ versions/ Implementation Notes Get a list of object versions from a collection Requests URL Parameters {api-root}  - the base URL of the API Root {id}        - the identifier of the Collection being requested {object-id} - the ID of the object being requested URL Filtering Parameters added_after  - a single timestamp            (e.g., ?added_after=...) limit        - a single integer              (e.g., ?limit=...) next         - a single string               (e.g., ?next=...)', 'vec_doc-11-oasis-taxii21-p58-132', 0, 287, 'v2.1.0', 'b0cd90819069ec7665f72698970a7beaf68fecbb233713af9dd22ecae3d1baba', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.8 Get Object Versions","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":132,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.8 Get Object Versions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p59-133', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.8 Get Object Versions', 59, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 59 of 79 spec_version - the specification version(s)  (e.g., ?match[spec_version]=...) Required Headers Accept: application/taxii+json;version=2.1 Successful Responses Response Codes 200 - The request was successful Required Headers Content-Type: application/taxii+json;version=2.1 X-TAXII-Date-Added-First: timestamp X-TAXII-Date-Added-Last: timestamp Payload versions Failure Responses Response Codes 400 - The server did not understand the request or filter parameters 401 - The client needs to authenticate 403 - The client does not have access to this versions resource 404 - The API Root, Collection ID and/or Object ID are not found, or the client does not have access to the versions resource 406 - The media type provided in the Accept header is invalid Required Headers Content-Type: application/taxii+json;version=2.1 Payload error Example GET Request GET /api1/collections/91a7b528-80eb-42ed-a74d-c6fbd5a26116/object/ indicator--252c7c11-daf2-42bd-843b-be65edca9f61/versions/ HTTP/1.1', 'vec_doc-11-oasis-taxii21-p59-133', 0, 277, 'v2.1.0', 'ca35071d39071df5650c248c11d35c6a0f68a07f6acfeba04d9de3cd3059d36b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.8 Get Object Versions","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":133,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.8 Get Object Versions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p60-134', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5.8 Get Object Versions', 60, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 60 of 79 Host: example.com Accept: application/taxii+json;version=2.1 GET Response HTTP/1.1 200 OK Content-Type: application/taxii+json;version=2.1 X-TAXII-Date-Added-First: timestamp X-TAXII-Date-Added-Last: timestamp { "versions": [ "2016-11-03T12:30:59.000Z", "2016-11-03T12:31:00.000Z" ] } 5.8.1 Versions Resource Resource Name: versions The versions resource is a simple wrapper around a list of versions. Property Name Type Description more (optional) boolean This property identifies if there is more content available based on the search criteria. The absence of this property means the value is false. versions (optional) list of type string The list of object versions returned by the request. If there are no versions returned, this key MUST be omitted, and the response is an empty object.', 'vec_doc-11-oasis-taxii21-p60-134', 0, 229, 'v2.1.0', '152b8d20c4afe974e54b120c909ed5f5d1c1a942488108ca9d6ea54fdfc04d92', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5.8 Get Object Versions","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":134,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5.8 Get Object Versions"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p62-135', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '7.1 Custom Properties', 62, 'It is understood that there will be cases where certain information exchanges can be improved by adding properties that are not specified nor reserved in this document; these properties are called Custom Properties. This section provides guidance and requirements for how TAXII Servers and Clients should use and interpret Custom Properties in order to extend TAXII in an interoperable manner. Note: The presence of Custom Properties may introduce variability of behavior depending on whether or not the TAXII Server or Client understands the Custom Properties. A reasonable strategy to minimize unwanted variations in behavior is to provide well defined and consistent rules for processing Custom Properties to any TAXII Server or Client that would be reasonably expected to parse them. 7.1.1 Requirements ● A TAXII resource MAY have any number of Custom Properties. ● Custom Property names MUST be in ASCII and MUST only contain the characters a–z (lowercase ASCII), 0–9, and underscore (_).', 'vec_doc-11-oasis-taxii21-p62-135', 0, 249, 'v2.1.0', 'ea3bf7f2c64d92d478e5a63bfd3655d579454310d3a91ecb92074087ff6ae0b7', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Custom Properties","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":135,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"7.1 Custom Properties"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p62-136', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '7.1 Custom Properties', 62, '● Custom Property names SHOULD start with “x_” followed by a source unique identifier (such as a domain name with dots replaced by underscores), an underscore and then the name. For example, x_example_com_customfield. ● Custom Property names MUST have a minimum length of 3 ASCII characters. ● Custom Property names MUST be no longer than 250 ASCII characters in length. ● Custom Property names that are not prefixed with “x_” may be used in a future version of the specification for a different meaning. If compatibility with future versions of this specifi cation is required, the “x_” prefix MUST be used. ● Custom Properties SHOULD only be used when there are no existing properties defined by the TAXII specification that fulfill that need. TAXII Servers that receive a TAXII Resource with one or more Custom Properties it does not understand MAY respond in one of two ways:', 'vec_doc-11-oasis-taxii21-p62-136', 0, 220, 'v2.1.0', '5bc5ae5f29ea6fbb0582ac729cdf948726c54d23e8ed994ea8cc159f6bcde550', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"7.1 Custom Properties","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":136,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"7.1 Custom Properties"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p62-137', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1. Either refuse to process the content further and respond to the message with an HTTP 422', 62, '(Unprocessable Entity) status code,', 'vec_doc-11-oasis-taxii21-p62-137', 0, 9, 'v2.1.0', '6a3349867e4945a4299f3e678c1b29c8843402b270bd6d84649fcf425478df40', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1. Either refuse to process the content further and respond to the message with an HTTP 422","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":137,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1. Either refuse to process the content further and respond to the message with an HTTP 422"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p62-138', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '2. or silently ignore non-understood properties and continue processing the message.', 62, 'TAXII Clients that receive a TAXII Resource with one or more Custom Properties it does not understand MAY silently ignore non-understood properties and continue processing the message. The reporting and logging of errors originating from the processing of Custom Properties depends on the TAXII Server and Client implementations and is therefore not covered in this specification. Examples { ..., "x_acmeinc_scoring": { "impact": "high",', 'vec_doc-11-oasis-taxii21-p62-138', 0, 110, 'v2.1.0', 'b813ac27c05e2b8e1e56d8df1c3b1b81d225a2589d105ad2630cde45f34f3b04', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"2. or silently ignore non-understood properties and continue processing the message.","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":138,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"2. or silently ignore non-understood properties and continue processing the message."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-139', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '8.1 TAXII Servers', 64, 'This section describes the types of TAXII Servers that can be implemented and which normative requirements those types of servers must conform to. 8.1.1 TAXII 2.1 Server A "TAXII 2.1 Server" is any software that conforms to the following normative requirements:', 'vec_doc-11-oasis-taxii21-p64-139', 0, 66, 'v2.1.0', 'e41c61d7990c315a07ed60e5c022478552d5262b4574ff4feab7dabab68b1f02', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"8.1 TAXII Servers","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":139,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"8.1 TAXII Servers"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-140', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1. It MUST support all requirements for a TAXII Collections Server as defined in section 8.1.2.', 64, '8.1.2 TAXII 2.1 Collections Server A "TAXII 2.1 Collections Server" is any software that conforms to the following normative requirements:', 'vec_doc-11-oasis-taxii21-p64-140', 0, 35, 'v2.1.0', '01c819064d1c7e9f3a5ccdea120c327592791f5f47b04cf2a319c3bbcd66f14e', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1. It MUST support all requirements for a TAXII Collections Server as defined in section 8.1.2.","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":140,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1. It MUST support all requirements for a TAXII Collections Server as defined in section 8.1.2."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-141', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4. It MAY support any features listed in section 8.3, Optional Server Features. Software supporting', 64, 'an optional feature MUST comply with the normative requirements of that feature.', 'vec_doc-11-oasis-taxii21-p64-141', 0, 20, 'v2.1.0', 'fc55eb19ee1487a266db22297267b16e34a8a76309873348b83b92dd6826a79a', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4. It MAY support any features listed in section 8.3, Optional Server Features. Software supporting","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":141,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4. It MAY support any features listed in section 8.3, Optional Server Features. Software supporting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-142', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '8.2 Mandatory Server Features', 64, 'This section defines the mandatory features that all TAXII Servers must implement. 8.2.1 TAXII Server Core Requirements', 'vec_doc-11-oasis-taxii21-p64-142', 0, 30, 'v2.1.0', '6b52a044a53a4a5ba8bf6402fb7b2f6583c88f87ca6bb26e915822f7abc33d5c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"8.2 Mandatory Server Features","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":142,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"8.2 Mandatory Server Features"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-143', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '1. It MUST define the URL of the Discovery API to be /taxii2/ and it MUST be located at the root of', 64, 'the server, e.g., https://example.com/taxii2/', 'vec_doc-11-oasis-taxii21-p64-143', 0, 12, 'v2.1.0', '09f81669f82ed51ed77773456720a9f8152f6767a3253265987f9bf666b47c76', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"1. It MUST define the URL of the Discovery API to be /taxii2/ and it MUST be located at the root of","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":143,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"1. It MUST define the URL of the Discovery API to be /taxii2/ and it MUST be located at the root of"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-144', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5. It MUST be capable of sending HTTP responses for features that it supports whose content is', 64, 'valid TAXII as defined in sections 3, 4, 5, and 6 or STIX as defined in [STIX Version 2.1].', 'vec_doc-11-oasis-taxii21-p64-144', 0, 23, 'v2.1.0', 'cf313d55fdb192c8832bdff71bf046cc9eeb7d5bfbb69937d451319c8bc06839', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5. It MUST be capable of sending HTTP responses for features that it supports whose content is","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":144,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5. It MUST be capable of sending HTTP responses for features that it supports whose content is"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-145', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '7. It SHOULD NOT reject a valid request that is missing the client User-Agent header.', 64, '8.2.2 HTTPS and Authentication Server Requirements', 'vec_doc-11-oasis-taxii21-p64-145', 0, 13, 'v2.1.0', 'b13c1c42303a6610c5b57ff13c5a3600939ace744ca11da46cba1d206242298d', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"7. It SHOULD NOT reject a valid request that is missing the client User-Agent header.","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":145,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"7. It SHOULD NOT reject a valid request that is missing the client User-Agent header."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-146', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '2. It MUST accept connections using TLS version 1.2 [RFC5246] and SHOULD accept connections', 64, 'using TLS version 1.3 [RFC8446] or higher.', 'vec_doc-11-oasis-taxii21-p64-146', 0, 11, 'v2.1.0', '901aee06c9af8726af4b27150f597d5e57e4468d044873ff29c85e99598b292b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"2. It MUST accept connections using TLS version 1.2 [RFC5246] and SHOULD accept connections","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":146,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"2. It MUST accept connections using TLS version 1.2 [RFC5246] and SHOULD accept connections"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-147', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '4. It SHOULD NOT accept any TLS 1.2 connections that use any of the cipher suites that are listed', 64, 'in the cipher suite blacklist in Appendix A of [RFC7540].', 'vec_doc-11-oasis-taxii21-p64-147', 0, 15, 'v2.1.0', '05058dbc3b3a0cc774a2ec15fb36f9da2becff3bc4bbfe5da52c9c4357d55e27', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"4. It SHOULD NOT accept any TLS 1.2 connections that use any of the cipher suites that are listed","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":147,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"4. It SHOULD NOT accept any TLS 1.2 connections that use any of the cipher suites that are listed"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p64-148', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '6. It MAY permit configurations that enable and/or disable all authentication schemes, including', 64, 'HTTP Basic authentication.', 'vec_doc-11-oasis-taxii21-p64-148', 0, 7, 'v2.1.0', '4032d3abd1e65d45356dc7d44e950072bb785a04e4de8e23e2b0703ff0934e9b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"6. It MAY permit configurations that enable and/or disable all authentication schemes, including","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":148,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"6. It MAY permit configurations that enable and/or disable all authentication schemes, including"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p65-149', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'section 1.6.9.', 65, '8. It MAY restrict access to clients by omitting specific objects, information, or optional properties from any TAXII response.', 'vec_doc-11-oasis-taxii21-p65-149', 0, 32, 'v2.1.0', 'd7d38e1cc16274c126aca10568d7910393e63fb3926f1aa8eb123344b0bb9105', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"section 1.6.9.","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":149,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"section 1.6.9."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p65-150', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '8.3 Optional Server Features', 65, 'This section defines the optional features that a TAXII Server MAY implement. 8.3.1 Client Certificate Verification TAXII 2.1 servers MAY choose to verify a client’s certificate and use it for authentication. TAXII Servers supporting client certificate verification and authentication MUST follow the normative requirements listed in this section. ● The default strategy for TAXII Servers authenticating and verifying certificates SHOULD be PKIX as defined in [RFC5280], [RFC6818], [RFC6125] et al. ● It MAY support other certificate verification policies such as Certificate Pinning.', 'vec_doc-11-oasis-taxii21-p65-150', 0, 146, 'v2.1.0', 'e53eb943378c8f38dbdc9084f4900777e02a26df5014a16417a6e1b34ef6cb4e', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"8.3 Optional Server Features","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":150,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"8.3 Optional Server Features"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p65-151', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '8.4 TAXII Clients', 65, 'This section describes the types of TAXII Clients that can be implemented and which normative requirements those types of clients must conform to. 8.4.1 TAXII 2.1 Client A "TAXII 2.1 Client" is any software that conforms to the following normative requirements:', 'vec_doc-11-oasis-taxii21-p65-151', 0, 66, 'v2.1.0', 'be98186785885f9872c13c63f865dd156b2c8741a11bf8bd6eca025735b496ec', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"8.4 TAXII Clients","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":151,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"8.4 TAXII Clients"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p65-152', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '2. It SHOULD use an HTTP User-Agent string to correctly identify the software name and version as', 65, 'defined in section 5.5.3 of [RFC7231]. 8.4.2 TAXII 2.1 Collections Client A "TAXII 2.1 Collections Client" is any software that exchanges CTI data with a TAXII 2.1 Collections Server or a TAXII 2.1 Server. A TAXII 2.1 Collections Client conforms to the following normative requirements:', 'vec_doc-11-oasis-taxii21-p65-152', 0, 72, 'v2.1.0', '427d13e11ef8394fdaf5b13d1b87a2dddcf6dc248c334264fb663955f238481f', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"2. It SHOULD use an HTTP User-Agent string to correctly identify the software name and version as","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":152,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"2. It SHOULD use an HTTP User-Agent string to correctly identify the software name and version as"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p65-153', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '8.5 Mandatory Client Features', 65, 'This section defines the mandatory features that all TAXII Clients MUST support. 8.5.1 HTTPS and Authentication Client Requirements', 'vec_doc-11-oasis-taxii21-p65-153', 0, 33, 'v2.1.0', 'bcfee6f9d45b5e0fc1908dd2826da38ed2fe64fe45a04bdbb5fe64c045681376', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"8.5 Mandatory Client Features","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":153,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"8.5 Mandatory Client Features"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p65-154', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '3. It SHOULD NOT use TLS 1.2 with any of the cipher suites that are listed in the cipher suite', 65, 'blacklist in Appendix A of [RFC7540].', 'vec_doc-11-oasis-taxii21-p65-154', 0, 10, 'v2.1.0', '281138c461c21036c28f3a774e358131522ce070354d5fef0e438098bce0109a', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"3. It SHOULD NOT use TLS 1.2 with any of the cipher suites that are listed in the cipher suite","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":154,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"3. It SHOULD NOT use TLS 1.2 with any of the cipher suites that are listed in the cipher suite"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p66-155', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'section 1.6.9.', 66, '8.5.2 Server Certificate Verification ● The default strategy for TAXII Clients authenticating and verifying the server''s TLS certificate SHOULD be PKIX as defined in [RFC5280], [RFC6818], [RFC6125] et al. ● TAXII Clients MAY support other certification verification policies such as: ○ Certificate Pinning: A single or limited set of either hard-coded or physically distributed pinned certificate authorities or end-entity certificates. ○ DANE: DNS-based Authentication of Named Entities [RFC7671]. Systems implementing DANE SHOULD also implement DNSSEC [RFC4033]. ○ Note that Self-Signed Certificates (like other certificates which cannot be verified by PKIX) MAY be supported via Certificate Pinning and/or DANE as noted above.', 'vec_doc-11-oasis-taxii21-p66-155', 0, 183, 'v2.1.0', '1420620997f701c9fde11e491ef95c0f09c47c2163a9d00c032d1d516bf0bfef', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"section 1.6.9.","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":155,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"section 1.6.9."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p67-156', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'section 1.6.9.', 67, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 67 of 79 Appendix A. Glossary API Root - A grouping of TAXII Channels, Collections, and related functionality. Channel - A publish-subscribe communications method where messages are exchanged. CTI - Cyber Threat Intelligence Collection - A logical group of CTI objects. Endpoint - A combination of a URL and HTTP method with defined behavior in TAXII. STIX - Structured Threat Information Expression (STIX) is a language and serialization format used to exchange cyber threat intelligence (CTI). STIX Content - STIX documents, including STIX Objects, grouped as STIX Bundles. STIX Object - A STIX Domain Object (SDO) or STIX Relationship Object (SRO). TAXII - Trusted Automated eXchange of Intelligence Information (TAXII) is an application layer protocol for the communication of cyber threat intelligence (CTI). TAXII Client - A software package that connects to a TAXII Server and supports the exchange of CTI. TAXII Server - A software package that supports the exchange of CTI.', 'vec_doc-11-oasis-taxii21-p67-156', 0, 274, 'v2.1.0', '02823cbe0fcf202f8fb481c18837768b0e31c7d848a85092d3b9ade26127b5de', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"section 1.6.9.","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":156,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"section 1.6.9."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p68-157', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'section 1.6.9.', 68, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 68 of 79 Appendix B. IANA Considerations This appendix contains the required information to register the TAXII media type with IANA. While some of the information here is only for IANA, implementers of TAXII should pay close attention to the security considerations and privacy considerations outlined in this appendix. This document defines the "application/taxii+json" media type Media type name:  application Media subtype name:  taxii+json Required parameters:  None Optional parameters:  version This parameter is used to designate the specification version of TAXII that is being used during HTTP content negotiation. Example: "application/taxii+json;version=2.1". The parameter value is of the form ''n.m'', where n is the major version and m the minor version, both unsigned integer values. Encoding considerations:  binary Encoding considerations are identical to those specified for the "application/json" media type. See [RFC8259]. Security considerations: These considerations are, in part, derived from Section 9 of the Resource-Oriented Lightweight Information Exchange [RFC8322]. This document defines a resource-oriented approach for exchanging cyber threat intelligence using HTTP [RFC7230] over TLS [RFC5246] and the JSON [RFC8259] Format.  As such, implementers must understand the security considerations described in those specifications. Security considerations relating to the generation and consumption of TAXII messages are similar to application/json and are discussed in Section 12 of [RFC8259]. The discovery API contains one or multiple URLs, therefor the security considerations stated in', 'vec_doc-11-oasis-taxii21-p68-157', 0, 432, 'v2.1.0', '3c7046c8e4016d5ab290ea48cfba47098099a478d7eadae14f0c4459fc76d9f9', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"section 1.6.9.","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":157,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"section 1.6.9."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p68-158', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 68, 'attempts of path traversal. Documents of "application/taxii+json" are simply request and response messages for an RPC like mechanism for searching, uploading and downloading Cyber Threat Intelligence (CTI) documents, most commonly STIX. The documents only contain metadata about the TAXII server, such as descriptions, versions of CTI or status response of the request. Documents do not contain active or executable content.', 'vec_doc-11-oasis-taxii21-p68-158', 0, 106, 'v2.1.0', 'bbb543f0372f72029de14e9993cf551bffd84f110a5358e4b6aeef1579ef16d4', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":158,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p69-159', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 69, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 69 of 79 Unicode is used to represent text such as descriptions in the format. The considerations documented by Unicode Technical Report #36: Unicode Security Considerations [ UNICODE] should be taken into account. To protect the confidentiality of a given resource provided by a TAXII implementation, requests for retrieval of a resource need to be authenticated to prevent unauthorized users from accessing the resource. It can also be useful to log and audit access to sensitive resources to verify that proper access controls remain in place over time. Access control to content made available using TAXII should use mechanisms that are appropriate to the sensitivity of the information. While the primitive authentication mechanism of HTTP Basic Authentication [RFC7617] is mandatory to implement for base level interoperability it is rarely appropriate for sensitive information.', 'vec_doc-11-oasis-taxii21-p69-159', 0, 250, 'v2.1.0', '349cc0ddd99721a51703b7663d5fe1546f4e2acf3fcf80d333e02127331f73bf', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":159,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p69-160', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 69, 'A number of authentication schemes are defined in the "HTTP Authentication Schemes" registry at IANA [IANA AUTH]. Of these, HTTP Origin- Bound Authentication (HOBA) [RFC7486] and SCRAM-SHA-256 [RFC7804] ("SCRAM" stands for "Salted Challenge Response Authentication Mechanism") provide improved security properties over HTTP Basic [RFC7617] and Digest [RFC7616] authentication schemes. However, sharing communities that are engaged in sensitive collaborative analysis and/or operational response for indicators and incidents targeting high-value information systems should adopt a suitably stronger user authentication solution, such as a risk-based or multi-factor approach.', 'vec_doc-11-oasis-taxii21-p69-160', 0, 169, 'v2.1.0', '240d83beb80d2f51ff69291785402b40f6e90e55cc996740bc746c6fba847918', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":160,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p69-161', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 69, 'Collaborating consortiums may benefit from the adoption of a federated identity solution, such as those based upon OAuth [RFC6749] with the JSON Web Token (JWT) [RFC7797], or SAML-core [SAML-core] ("SAML" stands for "Security Assertion Markup Language"), SAML-bind [SAML- bind], and SAML-prof [SAML-prof] for web-based authentication and cross-organizational single sign-on. Dependency on a trusted third-party identity provider implies that appropriate care must be exercised to sufficiently secure the identity provider. Any attacks on the federated identity system would present a risk to the consortium, as a relying party. Potential mitigations include deployment of a federation-aware identity provider that is under the control of the information- sharing consortium, with suitably stringent technical and management controls. It is recommended that all TAXII servers authenticate and authorize access to all collection data on a per-client basis using robust security methods.', 'vec_doc-11-oasis-taxii21-p69-161', 0, 246, 'v2.1.0', '3b4a8b59ea7025847761150b1823b0526017e27c8b42e2c60cfde560455f6cc6', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":161,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p69-162', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 69, 'While this specification defines HTTP Basic as a minimum suggested authentication mechanism, more advanced security authentication methods are recommended when products or deployments require stronger authentication and authorization frameworks for accessing or posting data to the TAXII server. Authorization of resource representations is the responsibility of the source system, i.e., based on the authenticated user identity associated with an HTTP(S) request. The required authorization policies that are to be enforced must therefore be managed by the security administrators of the source system. Various authorization architectures would be suitable for this purpose, such as Role-Based Access Control (RBAC) [NIST RBAC] and/or Attribute-Based Access Control (ABAC), as embodied in the eXtensible Access Control Markup Language (XACML) [XACML].', 'vec_doc-11-oasis-taxii21-p69-162', 0, 213, 'v2.1.0', '38ace71a56f05d458bda20aef2da509cd49a68adfd32d3d7a26b5deca71bd7d6', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":162,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p69-163', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 69, 'In particular, implementers adopting XACML may benefit from the capability to represent their authorization policies in a standardized, interoperable format. Note that implementers are free to choose any suitable authorization mechanism that is capable of fulfilling the policy enforcement requirements relevant to their consortium and/or organization. While the authentication and confidentiality for the TAXII session is done at a lower level via the transport mechanism (HTTPS), this does not obviate the consumer (server or client) from validating the format and contents of the documents sent in a session. This validation sh ould includes checking various limits, such as document size limits, to limit the risk of the other party attempting to attack the service.', 'vec_doc-11-oasis-taxii21-p69-163', 0, 193, 'v2.1.0', '0f4a6933c0133c768ae78d26ab72066612e4a31b27b986415200f4bc4036851e', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":163,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p70-164', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 70, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 70 of 79 Additional security requirements such as enforcing message-level security at the destination system could supplement the security enforcements performed at the source system; however, these destination-provided policy enforcements are out of scope for this specification. Implementers requiring this capability should consider leveraging, for example, the <RIDPolicy> element in the RID schema. Refer to Section 9 of [RFC6545] for more information. Additionally, the underlying JSON serialization used in the representation can offer encryption and message authentication capabilities. For example, JSON Web Encryption [RFC7516] and JSON Web Signature [RFC7515], can provide such mechanisms. TAXII Servers may manage response volume in different ways. Implementers should be aware that a search request may return more objects than is prudent to return in a single HTTP Response.', 'vec_doc-11-oasis-taxii21-p70-164', 0, 250, 'v2.1.0', '06f41553836ab4631d5784db293449327eaeb7f226d5a79cb8573d808e93df6c', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":164,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p70-165', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 70, 'To mitigate this, TAXII servers should consider implementing restrictions on the number of objects it will return in a single HTTP response. TAXII provides clients a rich set of filtering and query options to return specific results from repositories of CTI data. As such, TAXII servers should implement protections against queries that can potentially consume a significant amount of resources and prevent the server from functioning in a normal way. TAXII defines an optional error message that may contain sensitive application data. Implementers should ensure that they do not leak descriptive text or application return codes for things that a user may not have access to, for example leak info about existence of something, implementation of something, vs. just not having access. Note: Despite TAXII searching and returning STIX objects, this format does not encapsulate any CTI content. It is expected that CTI documents will be sent with the appropriate mime -type.', 'vec_doc-11-oasis-taxii21-p70-165', 0, 244, 'v2.1.0', 'f70033c3c4872c208afb02617cae04ed85e6e6811674a9b583df9e7b77eb40c0', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":165,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p70-166', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 70, 'For these, consult their own security consideration sections. As the next URL parameter is a client provided property, care must be taken that it is not blindly trusted as the same value that the server returned as part of the TAXII Envelope. This means it MUST NOT be implicitly trusted, and the value MUST be reevaluated in the context of the provided query such that incorrect data (data that the client is not authorized to have or not part of the query set) is not returned. Privacy considerations These considerations are, in part, derived from Section 10 of the Resource-Oriented Lightweight Information Exchange [RFC8322]. The documents contain various descriptions and other text. There is no expectation that these will contain private information, but as some may be user provided, there is no guarantee that a user will not inadvertently include private data.', 'vec_doc-11-oasis-taxii21-p70-166', 0, 218, 'v2.1.0', '8025240f7d4b9af173a99a06150e90aabf123e7ccaba9101a52366e9b6382842', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":166,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p70-167', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 70, 'It is expected that the client or server authenticate the other party through the transport mechanism before sending any possible private data. As the protocol is about sharing data, it is expected that the parties understand their obligations in keeping relevant data private. Adoption of the information-sharing approach described in this document will enable users to more easily perform correlations across separate, and potentially unrelated, cybersecurity information providers. A client may succeed in assembling a data set that would not have been permitted within the context of the authorization policies of either provider when considered individually. Thus, providers may face a risk of an attacker obtaining an access that const itutes', 'vec_doc-11-oasis-taxii21-p70-167', 0, 187, 'v2.1.0', 'b8a8dc4cbdb02fe2d72d05cee53d7445f1b10a9ac11f99b3be2b9c7e179f602b', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":167,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p71-168', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 71, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 71 of 79 an undetected separation of duties (SOD) violation. It is important to note that this risk is not unique to this specification, and a similar potential for abuse exists with any other cybersecurity information-sharing protocol. However, the wide availability of tools for HTTP clients implies that the resources and technical skills required for a successful exploit may be less than it was previously. This risk can be best mitigated through appropriate vetting of the client at the time of account provisioning. In addition, any increase in the risk of this type of abuse should be offset by the corresponding increase in effectiveness that this specification affords to the defenders. Overall, privacy concerns in TAXII can be mitigated by following security considerations and by the careful use of the content exchanged via TAXII.', 'vec_doc-11-oasis-taxii21-p71-168', 0, 239, 'v2.1.0', 'a48523e35f8af45df51ff82a7cd29541329a7da440ed3224475b1821e3101d0e', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":168,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p71-169', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and', 71, 'Interoperability considerations: The TAXII specification specifies the format of conforming messages and the interpretation thereof. In addition, the OASIS Cyber Threat Intelligence (CTI) Technical Committee has defined interoperability tests to ensure conforming products and solutions can exchange TAXII documents. Published specification: TAXII Version 2.1 OASIS Committee Specification 01 http://docs.oasis-open.org/cti/taxii/v2.1/cs01/taxii-v2.1-cs01.html Cited in the "OASIS Standards" document: https://www.oasis-open.org/standards#oasiscommiteespecs, from https://www.oasis-open.org/standards#taxii2.1 Applications which use this media: TAXII is an application layer protocol for the communication of cyber threat information including STIX in a simple and scalable manner. Fragment identifier considerations:  None Restrictions on usage:  None Additional information:', 'vec_doc-11-oasis-taxii21-p71-169', 0, 219, 'v2.1.0', 'e04484899a4a7a0c60c9d3159b099b1ed9dc596127caf2bb0cbd380f4412e8a1', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":169,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"Section 6 of [RFC1738] should be consulted especially in regard to parsing relative URLs and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p71-170', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5. Object Identifiers: None', 71, 'Person and email to contact for further information:  Chet Ensign (chet.ensign@oasis -open.org) Intended usage:  COMMON Author:', 'vec_doc-11-oasis-taxii21-p71-170', 0, 32, 'v2.1.0', 'e564b35573498138e7168ee0b3b4607fe3d3b521f01f7c52fca025bac18c47d6', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5. Object Identifiers: None","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":170,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5. Object Identifiers: None"}');
