INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p78-181', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5. Object Identifiers: None', 78, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 78 of 79 Appendix D. Revision History Revision Date Editor(s) Changes Made 01 2018-04-10 Bret Jordan Drew Varner Initial Version GitHub Issues: 1, 8, 9, 10, 11, 12, 17, 18, 19, 20, 21, 23, 25, 26, 28, 29, 30, 31, 34, 35, 36, 39, 41, 43, 48, 49, 51, 53, 54, 56, 57, 62, 63 02 2018-05-18 Bret Jordan Drew Varner Fix typos, add clarifying text in some cases, changed DNS SRV record name, changed status resource, and made other minor changes. GitHub Issues: 47, 65, 66, 67, 70, 73, 74, 75 03 2018-07-12 Bret Jordan Drew Varner Reformatted the endpoint definitions, added an endpoint to DELETE an object, and added a versions endpoint to object by ID. Added IANA Considerations Appendix. Changed angle brackets "<>" in the URL parameters to be curly brackets "{}" to better align with API documentation best practices.  Added non-normative references section. GitHub Issues: 37, 38, 58, 76, 78, 79, 80, 82, 84 04 2018-11-16 Bret Jordan Drew Varner Renamed resource subtype manifest- entry to manifest-record. Added clarifying text for each endpoint on error codes to be returned. Removed the STIX media type and STIX Bundle and replaced it with a TAXII Envelope. Added a limit URL parameter and a spec_versions match filter parameter. Added clarifying text around TAXII timestamps needing microsecond precision. Cleaned up text and deemphasized content other than STIX. GitHub Issues: 52, 87, 88, 89, 90, 91, 92, 93, 94', 'vec_doc-11-oasis-taxii21-p78-181', 0, 382, 'v2.1.0', 'b4057b05905181d31e938357e69fafe8f172d069d198a38db26eda9d8ab86701', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5. Object Identifiers: None","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":181,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5. Object Identifiers: None"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p79-182', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', '5. Object Identifiers: None', 79, 'taxii-v2.1-os  10 June 2021 Standards Track Work Product Copyright © OASIS Open 2022. All Rights Reserved. Page 79 of 79 05 2018-12-03 Bret Jordan Drew Varner Minor editorial change form WD04 and added User-Agent text. GitHub Issues: 86 06 2019-01-24 Bret Jordan Drew Varner Changed envelope to contain a list of objects instead of containing a STIX Bundle. Fixed some text around the new spec version filter and made sure the filters and pagination elements are on all appropriate endpoints. GitHub Issues: 32, 42, 44, 50, 59, 60, 81, 83, 95, 96, 97, 98, 99, 103 07 2019-07-16 Bret Jordan Drew Varner Added language in 3.4.1 to support objects with no version information. Changes from "records" to "objects" in', 'vec_doc-11-oasis-taxii21-p79-182', 0, 178, 'v2.1.0', '3883b029d917ae3348c8eb5b8b558c88f9deceef8f4a9c572ce9bc5158320b8e', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"5. Object Identifiers: None","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":182,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"5. Object Identifiers: None"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-11-oasis-taxii21-p79-183', 'doc-11-oasis-taxii21', 'doc-11-oasis-taxii21', 'section 3.4 and Appendix B.', 79, '08 2019-09-17 Bret Jordan Drew Varner Fixed broken links identified by OASIS Admin and two typos. Added informational and example text and put it in section 3.5, moving the other sections down and fixed all of the references. 09 2019-10-17 Bret Jordan Drew Varner Fix two grammar typos in the conformance section. Added the concept of a "next" value to pagination. This impacted sections 3.4, 3.5, and 3.7. Removed some references to the STIX media type that we no longer use in TAXII. Added some text to the security considerations for handling the "next" value in pagination. Add the "next" url parameter to appropriate endpoints. 10 2019-11-12 Bret Jordan Drew Varner Added a clause to the version property of the manifest resource and the status resource to address SCOs that do not have created or modified timestamps.', 'vec_doc-11-oasis-taxii21-p79-183', 0, 206, 'v2.1.0', 'c870447bea75541eb350187bc741ef911a77fd566a3d6b028a42a64c7417fcd0', '{"document_id":"doc-11-oasis-taxii21","document_title":"OASIS TAXII v2.1 Specification","chapter":"UNKNOWN","section":"section 3.4 and Appendix B.","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"CTI_STANDARDS","authority_tier":0,"chunk_seq":183,"source_path":".zayron/knowledge/physical-15/11-oasis-taxii21.pdf","section_path":"section 3.4 and Appendix B."}');
